L["quest log full"] = "журнал заданий полон"
L["can't take it"] = "не может взять"
L["too far to share"] = "слишком далеко, чтобы поделиться"
L["level too low"] = "слишком низкий уровень"
L["another class"] = "другой класс"
L["another race"] = "другая раса"
L["level %d, needs %d"] = "уровень %d, нужен %d"
L["Waiting on %s"] = "Ждём игрока %s"
L["Everyone's ready"] = "Все готовы"
L["Waiting on %s: %s"] = "Ждём игрока %s: %s"
L["%s still needs %d %s"] = "%s: ещё нужно %d %s"
L["%s (%s)"] = "%s (%s)"
L["%s: other guide"] = "%s: другой гайд"
L["Party: %s"] = "Группа: %s"
L["For %s: she still needs %d"] = "Для %s: ей ещё нужно %d"
L["For %s: he still needs %d"] = "Для %s: ему ещё нужно %d"
L["For %s: still needs %d"] = "Для %s: ещё нужно %d"
L["Party members who run Polestar see your counts under their quest goals, your step and your level. Hidden addon messages to your party only; nothing goes to chat."] = "Участники группы с Polestar видят ваши счётчики под своими целями заданий, ваш шаг и ваш уровень. Скрытые сообщения аддона только вашей группе; в чат ничего не уходит."
L["Their counts under your quest goals, and who lacks a quest you took, with a Share button."] = "Их счётчики под вашими целями заданий и у кого нет взятого вами задания, с кнопкой «Поделиться»."
L["Wait for the group"] = "Ждать группу"
L["When a party member on your quest still needs an objective you finished, the step and its turn-in wait and the arrow leads to what they need. Members in another zone or offline for 2 minutes don't hold you; the party line offers Go on without them."] = "Если участнику группы на вашем задании ещё нужна задача, которую вы выполнили, шаг и сдача ждут, а стрелка ведёт к тому, что ему нужно. Участники в другой зоне или не в сети 2 минуты вас не держат; строка группы предлагает «Идти без них»."
L["Say who still needs quest loot"] = "Показывать, кому ещё нужна добыча для заданий"
L["On a loot window or roll, a line under a quest item a party member still needs and you don't. Nothing is passed or said for you."] = "В окне добычи или при розыгрыше — строка под предметом задания, который ещё нужен участнику группы, но не вам. За вас ничего не передаётся и не пишется."
L["Party panel"] = "Панель группы"
L["Opens by itself when someone in your party runs Polestar too: each member's level, step and what they still need of yours; click a name to point the arrow at them. Closed, it stays closed; /polestar party opens it again."] = "Открывается само, когда у кого-то в группе тоже есть Polestar: уровень каждого участника, его шаг и что ему еще нужно из ваших заданий; щелкните имя, чтобы направить на него стрелку. Если закрыть, останется закрытым; /polestar party открывает снова."
L["Tell my party about objectives and ready quests"] = "Сообщать группе о задачах и готовых к сдаче заданиях"
L["A party chat line with the quest's link when you finish its objectives, and one when the quest is ready to turn in. Everyone in the party sees it, Polestar or not. Never solo or in a raid."] = "Строка в чате группы со ссылкой на задание, когда вы выполняете его задачи, и ещё одна, когда задание можно сдать. Её видит вся группа, с Polestar или без. Никогда в одиночку или в рейде."
L["Tell my party when I loot an item that starts a quest"] = "Сообщать группе, когда я получаю предмет, начинающий задание"
L["A party chat line with the item's link and the quest it starts."] = "Строка в чате группы со ссылкой на предмет и задание, которое он начинает."
L["Show my own lines in my chat too"] = "Показывать мои строки и в моём чате"
L["Off: your party sees the lines Polestar says for you, and your chat stays clear of them."] = "Выключено: группа видит строки, которые Polestar пишет за вас, а ваш чат остаётся без них."
L["Hide other players' Polestar lines"] = "Скрывать строки Polestar других игроков"
L["Party members' Polestar lines leave your chat. Shown, they carry Polestar's star."] = "Строки Polestar участников группы исчезают из вашего чата. Видимые, они отмечены звездой Polestar."
L["Only when someone in the party doesn't have Polestar"] = "Только если у кого-то в группе нет Polestar"
L["Nothing goes to chat while everyone in your party runs Polestar: they see your progress in their guide."] = "В чат ничего не уходит, пока у всех в группе есть Polestar: они видят ваш прогресс в своём гайде."
L["%s asks you to sync to their guide."] = "%s предлагает синхронизироваться с его гайдом."
L["You'll switch to %s."] = "Вы перейдёте на %s."
L["Their step: %s"] = "Его шаг: %s"
L["You're past their step: your guide stays where you are."] = "Вы уже дальше его шага: ваш гайд остаётся на месте."
L["%s is past these, which you haven't done: %s"] = "%1$s уже прошёл эти шаги, которые вы не выполнили: %2$s"
L["You've done these already, so your guide passes them: %s"] = "Вы это уже выполнили, поэтому гайд их пропустит: %s"
L["%s asked you to sync to their guide, but it isn't for your character or your copy lacks their step."] = "%s предложил синхронизироваться с его гайдом, но гайд не для вашего персонажа или в вашей копии нет его шага."
L["No room for another guide tab: close one, then ask %s again."] = "Нет места для ещё одной вкладки гайда: закройте одну и попросите %s снова."
L["%s synced to your guide."] = "%s синхронизировался с вашим гайдом."
L["%s declined to sync."] = "%s отказался синхронизироваться."
L["%s can't sync: your guide isn't for their character, or their copy lacks your step."] = "%s не может синхронизироваться: ваш гайд не для его персонажа или в его копии нет вашего шага."
L["%s is already on your step."] = "%s уже на вашем шаге."
L["No one else in your party has been heard running Polestar yet."] = "Пока ни у кого из группы не замечен Polestar."
L["You have no step to sync to: open a guide you haven't finished."] = "Нет шага для синхронизации: откройте незавершённый гайд."
L["You asked a moment ago: wait %d seconds."] = "Вы уже просили только что: подождите %d с."
L["The game didn't send it: try again in a moment."] = "Игра не отправила запрос: попробуйте ещё раз чуть позже."
L["Asked your party to sync to your step. Each of them chooses."] = "Группе предложено перейти на ваш шаг. Каждый решает сам."
L["%s asked you to sync to their guide; that prompt can't show with the gamepad interface."] = "%s предложил синхронизироваться с его гайдом; этот запрос нельзя показать в интерфейсе геймпада."
L["%s is on Polestar %s: your guides can differ. A newer version is out."] = "У %s Polestar %s: ваши гайды могут различаться. Вышла новая версия."
L["%s is on Polestar %s: your guides can differ."] = "У %s Polestar %s: ваши гайды могут различаться."
L["Party sync is on: you and your party see each other's quest progress. Turn it off in Options."] = "Синхронизация группы включена: вы и ваша группа видите прогресс заданий друг друга. Выключить ее можно в настройках."
L["Ask other players' Polestar which version it is"] = "Спрашивать версию Polestar у других игроков"
L["Up to 10 hidden addon whispers a session, to players of your faction you target or mouse over outside cities, combat and dungeons, and an answer to theirs: only the version number, so Polestar can tell you when a newer one is out. Off: none sent or answered."] = "До 10 скрытых шепотов аддона за сессию игрокам вашей фракции, которых вы выбираете целью или на которых наводите курсор вне городов, боя и подземелий, и ответ на их шепот: только номер версии, чтобы Polestar мог сообщить о выходе новой. Выкл.: ничего не отправляется и не отвечается."

