L["Rewards & gear"] = "Награды и экипировка"
L["Gear advice"] = "Советы по экипировке"
L["Score items for your class and talents and point out upgrades."] = "Оценивать предметы под ваш класс и таланты и указывать улучшения."
L["Stat weights"] = "Веса характеристик"
L["Which levelling weights score your items. Automatic follows the talent tree with the most points."] = "Какие веса для прокачки оценивают предметы. Авто следует ветке талантов с наибольшим числом очков."
L["Tooltip comparison"] = "Сравнение в подсказке"
L["Show on item tooltips how much better or worse an item is than what you wear."] = "Показывать в подсказке предмета, насколько он лучше или хуже надетого."
L["Reward pick in the guide"] = "Выбор награды в гайде"
L["Under a turn-in step, name the reward to take: an upgrade with its gain, else the best one you can use. The marks on the game's reward panel are under Quest rewards."] = "Под шагом сдачи называть награду: улучшение с приростом, иначе лучшую из доступных. Метки на панели наград игры — в разделе «Награды за задания»."
L["Reward pick on tooltips"] = "Выбор награды в подсказках"
L["On a quest reward's tooltip, say whether it is the upgrade to take."] = "В подсказке награды за задание сообщать, стоит ли ее брать как улучшение."
L["Upgrade threshold"] = "Порог улучшения"
L["Smaller gains than this are not called upgrades."] = "Меньший прирост не считается улучшением."
L["Pair with bag items"] = "Учитывать предметы в сумках"
L["Against a worn two-hander, weigh a one-hander together with the best off-hand piece in your bags."] = "Против надетого двуручного оценивать одноручное вместе с лучшим предметом для левой руки из сумок."
L["Upgrade arrows in bags"] = "Стрелки улучшений в сумках"
L["A green arrow on each item in your bags that is an upgrade for your spec, in the game's bags and in Baganator."] = "Зеленая стрелка на каждом предмете в сумках, который является улучшением для вашей специализации, — в сумках игры и в Baganator."
L["Manage custom weights"] = "Управление своими весами"
L["Import a Pawn scale string, and use, rename, export or delete the scales you have."] = "Импортируйте строку шкалы Pawn, а также используйте, переименовывайте, экспортируйте или удаляйте уже имеющиеся шкалы."
L["Leave bag arrows to Pawn"] = "Стрелки в сумках — от Pawn"
L["Pawn is installed and draws its own upgrade arrows in your bags. Turn this on to hide Polestar's, so an item does not carry two."] = "Pawn установлен и сам показывает в сумках стрелки улучшений. Включите этот параметр, чтобы скрыть стрелки Polestar и на предмете не было двух стрелок."
L["Manage"] = "Управление"

-- Maps/Maps.lua
L["Dungeons and travel"] = "Подземелья и перемещения"
L["Dungeon entrances"] = "Входы в подземелья"
L["Marks each dungeon entrance with its level range. Click to open the dungeon's guide, or to set a waypoint when there is none; Shift-click always sets a waypoint. Needs the Codex pack."] = "Отмечает вход в каждое подземелье с диапазоном уровней. Щелчок открывает гайд подземелья или ставит путевую точку, если гайда нет; Shift-щелчок всегда ставит путевую точку. Нужен пакет Codex."
L["Flight masters"] = "Распорядители полетов"
L["Your faction's and neutral flight masters: green when known, amber when not yet discovered. The tooltip lists destinations and flight times."] = "Распорядители полетов вашей фракции и нейтральные: зеленые — известные, янтарные — еще не открытые. В подсказке — пункты назначения и время полета."
L["Boats and zeppelins"] = "Корабли и дирижабли"
L["Docks, zeppelin towers and the Deeprun Tram, with where they go."] = "Причалы, башни дирижаблей и Подземный поезд с пунктами назначения."
L["Inns"] = "Таверны"
L["Innkeepers; the one your Hearthstone is bound to is marked."] = "Хозяева таверн; отмечен тот, к кому привязан камень возвращения."
L["Travel icons on the minimap"] = "Значки перемещений на мини-карте"
L["Shows the flight masters, docks and inns turned on here on the minimap as well."] = "Показывает включенные здесь распорядители полетов, причалы и таверны также на мини-карте."
L["Unexplored areas"] = "Неисследованные области"
L["Shows the parts of each zone you have not explored yet, so the whole map is there before you visit. Tinted keeps them apart from where you have been."] = "Показывает неисследованные части каждой зоны, чтобы карта была видна целиком до посещения. С оттенком они отличаются от посещенных."
L["Hidden"] = "Скрыты"
L["Revealed"] = "Открыты"
L["Revealed and tinted"] = "Открыты с оттенком"
L["Zone level ranges"] = "Уровни зон"
L["Shows each zone's level range on the continent and zone maps, coloured by difficulty for your level."] = "Показывает диапазон уровней каждой зоны на картах континента и зоны, с цветом сложности для вашего уровня."
L["Coordinates"] = "Координаты"
L["Shows your position and the cursor's position under the world map."] = "Показывает под картой ваше положение и положение курсора."
L["Coordinates on the minimap"] = "Координаты на мини-карте"
L["A small readout of your position at the bottom of the minimap."] = "Небольшой показ вашего положения внизу мини-карты."
L["Quality of Life"] = "Удобство"
L["Travel"] = "Перемещения"
L["Flight timer"] = "Таймер полета"
L["While flying, shows the destination and the time left. Learns each route's real duration for this character; drag to move."] = "В полете показывает пункт назначения и оставшееся время. Запоминает реальную длительность каждого маршрута для персонажа; можно перетащить."
L["Forget learned flight times"] = "Забыть время полетов"
L["Clears this character's recorded flight durations; estimates are used until they are flown again."] = "Удаляет записанное время полетов персонажа; до новых полетов используются оценки."
L["Learned flight times cleared."] = "Записанное время полетов удалено."
L["Trackers"] = "Трекеры"
L["Instances"] = "Подземелья"
L["Track instances"] = "Отслеживать подземелья"
L["Records dungeon and raid entries, time and experience per run. /pole instances lists them."] = "Записывает входы в подземелья и рейды, время и опыт за проход. /pole instances выводит список."
L["Compact display"] = "Компактный вид"
L["Shows the hourly instance count and the current run while it matters; drag to move."] = "Показывает число подземелий за час и текущий проход, когда это важно; можно перетащить."
L["Instances per hour"] = "Подземелий в час"
L["Classic allows 5 new instances per hour per account. Forever may differ; adjust if it does."] = "В Classic разрешено 5 новых подземелий в час на учетную запись. В Forever может отличаться; при необходимости измените."
L["Instances per day"] = "Подземелий в сутки"
L["Classic Era allows 30 new instances per 24 hours per account; 0 ignores the daily cap. Forever may differ."] = "В Classic Era разрешено 30 новых подземелий за 24 часа на учетную запись; 0 — без суточного лимита. В Forever может отличаться."
L["Clear instance history"] = "Очистить историю подземелий"
L["Forgets recorded entries and runs (the server's own limit is not affected)."] = "Забывает записанные входы и проходы (лимит сервера не меняется)."
L["Minimap button"] = "Кнопка у миникарты"
L["Forget"] = "Забыть"
L["Minimap"] = "Миникарта"
L["A Polestar button on the edge of the minimap. Click to hide or show Polestar, right-click for a menu, drag to move it."] = "Кнопка Polestar на краю миникарты. Щелчок скрывает или показывает Polestar, правый щелчок открывает меню, перетаскивание перемещает её."

