-- QoL/Death.lua
L["Run back to your corpse: %s (~%s). The Spirit Healer costs %s of resurrection sickness."] = "Бегите к телу: %s (~%s). Целитель душ стоит %s слабости после воскрешения."
L["Run back to your corpse: %s (~%s)."] = "Бегите к телу: %s (~%s)."
L["Resurrect at the Spirit Healer (%s): no resurrection sickness at your level."] = "Воскреснуть у целителя душ (%s): на вашем уровне нет слабости."
L["Resurrect at the Spirit Healer (%s): your corpse is %s away, longer than %s of sickness."] = "Воскреснуть у целителя душ (%s): тело в %s, дольше, чем %s слабости."
L["Resurrect at the Spirit Healer (%s)."] = "Воскреснуть у целителя душ (%s)."
L["Your corpse"] = "Ваше тело"
L["Spirit Healer"] = "Целитель душ"
L["Run back to %s, your corpse is inside: %s (~%s)."] = "Вернитесь в %s, ваше тело внутри: %s (~%s)."
