-- QoL/Options.lua
L["Off by default: %s does this too."] = "По умолчанию выкл.: это уже делает %s."
L["Buttons"] = "Кнопки"
L["Action buttons"] = "Кнопки действий"
L["Quest item button"] = "Кнопка предмета задания"
L["Highlight the step's item in your bags"] = "Подсвечивать предмет шага в сумках"
L["Polestar: step item"] = "Polestar: предмет шага"
L["A button for the current step's quest item, with count, cooldown and range. Bind it under Key Bindings > AddOns."] = "Кнопка для предмета задания текущего шага: количество, перезарядка и дальность. Назначьте клавишу в Назначение клавиш > Модификации."
L["Target button"] = "Кнопка цели"
L["Targets the current step's mobs by name, or the NPCs it sends you to when it has no mob; each click moves to the next name. Bindable."] = "Выбирает целью противников текущего шага по имени, а если их нет — НИП, к которым он отправляет; каждый щелчок переходит к следующему имени. Можно назначить клавишу."
L["Show who it targets"] = "Показывать, кого выбирает"
L["The target button's icon shows what you do next: talk, accept, turn in, kill or loot, a skull for an elite, rare or boss, or their face once you have seen them. Their name sits beside it, green for a friendly NPC, red for a mob, gold for an elite or rare, with small icons for the names after it."] = "Значок кнопки цели показывает, что делать дальше: поговорить, взять, сдать, убить или обыскать; череп для элиты, редкого или босса, или их лицо, когда вы их уже видели. Рядом имя: зелёное для дружественного НИП, красное для противника, золотое для элиты или редкого, и маленькие значки для следующих имён."
L["Name new targets in chat"] = "Сообщать о новых целях в чат"
L["When the target button's names change, one line in chat lists them (\"Targeting: ...\"). Only you see it."] = "Когда имена кнопки цели меняются, строка в чате перечисляет их («Цель: ...»). Видите её только вы."
L["Targeting: %s"] = "Цель: %s"
L["Where the target's name shows around the target button: right, left, above or below."] = "Где показывать имя цели рядом с кнопкой цели: справа, слева, сверху или снизу."
L["Right"] = "Справа"
L["Left"] = "Слева"
L["Above"] = "Сверху"
L["Below"] = "Снизу"
L["Reset button positions"] = "Сбросить положение кнопок"
L["Put the buttons back in their default spot."] = "Вернуть кнопки на место по умолчанию."
L["Quest rewards"] = "Награды за задания"
L["Mark quest rewards"] = "Отмечать награды заданий"
L["On the reward choices, a green arrow marks each upgrade for your spec (with Gear advice on), a thin frame in your accent colour the one to take, and a coin the one that sells for most."] = "Среди наград зеленая стрелка отмечает улучшения для вашей специализации (при включенных советах по экипировке), тонкая рамка цвета акцента — ту, что стоит взять, а монета — самую дорогую при продаже."
L["Take the best reward"] = "Брать лучшую награду"
L["Chooses that reward for you when you complete the quest. Hold Shift to choose yourself."] = "Выбирает эту награду за вас при сдаче задания. Удерживайте Shift, чтобы выбрать самому."
L["Wear reward upgrades"] = "Надевать улучшения"
L["Puts on what a turn-in gives when it is an upgrade for your spec (with Gear advice on), once it reaches your bags and you are out of combat. Hold Shift at the turn-in to skip."] = "Надевает полученную за задание вещь, если это улучшение для вашей специализации (при включенных советах по экипировке), как только она окажется в сумках и вы выйдете из боя. Удерживайте Shift при сдаче, чтобы пропустить."
L["Faster questing"] = "Быстрые задания"
L["Instant quest text"] = "Мгновенный текст заданий"
L["Shows quest text at once instead of fading it in (Forever's own option)."] = "Показывает текст задания сразу, без плавного появления (настройка самой Forever)."
L["Skip single-option gossip"] = "Пропускать диалоги без выбора"
L["Faster auto-loot"] = "Быстрый автосбор добычи"
L["Takes the whole corpse at once when auto-loot is on."] = "Забирает всю добычу сразу при включенном автосборе."
L["Hide combat errors"] = "Скрывать ошибки боя"
L["Hides \"Not enough rage\", \"Out of range\" and cooldown messages. Other errors still show."] = "Скрывает «Недостаточно ярости», «Слишком далеко» и сообщения о перезарядке. Прочие ошибки видны."
L["Open the flight map"] = "Открывать карту полетов"
L["Talking to a flight master opens the map directly. Hold Shift for the gossip."] = "Разговор с распорядителем полетов сразу открывает карту. Удерживайте Shift для диалога."
L["Mark the route's destination"] = "Отмечать пункт маршрута"
L["Marks where the travel route flies next on the flight map. You still choose the flight."] = "Отмечает на карте полетов, куда дальше летит маршрут. Полет вы выбираете сами."
L["Death"] = "Смерть"
L["Corpse or Spirit Healer"] = "Тело или Целитель душ"
L["As a ghost, points the arrow at the faster way back: your corpse or the nearest Spirit Healer."] = "В виде призрака стрелка указывает более быстрый путь: к телу или к ближайшему Целителю душ."
L["Release in battlegrounds"] = "Отпускать дух на полях боя"
L["Releases your spirit at once when you die in a battleground, unless you can resurrect yourself or someone offers to. Hold Shift to stay."] = "Сразу отпускает дух при смерти на поле боя, если вы не можете воскреснуть сами и вам не предлагают воскрешение. Удерживайте Shift, чтобы остаться."
L["Social"] = "Общение"
L["Requests"] = "Запросы"
L["Accept summons"] = "Принимать призыв"
L["Takes a summon at once, unless you are in combat. Hold Shift to decide yourself."] = "Сразу принимает призыв, если вы не в бою. Удерживайте Shift, чтобы решить самому."
L["Accept resurrections"] = "Принимать воскрешение"
L["Takes a resurrection as soon as it can, unless the caster is in combat. Never in Hardcore. Hold Shift to decide yourself."] = "Принимает воскрешение как можно скорее, если заклинатель не в бою. Никогда в режиме Hardcore. Удерживайте Shift, чтобы решить самому."
L["Join friends' parties"] = "Вступать в группы друзей"
L["Accepts party invitations from friends, Battle.net friends and your guild, unless joining would leave a queue. Hold Shift to decide yourself."] = "Принимает приглашения в группу от друзей, друзей Battle.net и гильдии, если это не выбросит вас из очереди. Удерживайте Shift, чтобы решить самому."
L["Blocking"] = "Блокировка"
L["Decline other party invitations"] = "Отклонять прочие приглашения в группу"
L["Declines party invitations from anyone who is not a friend or in your guild."] = "Отклоняет приглашения в группу от всех, кто не друг и не в вашей гильдии."
L["Decline guild invitations"] = "Отклонять приглашения в гильдию"
L["Declines guild invitations, except from friends."] = "Отклоняет приглашения в гильдию, кроме как от друзей."
L["Decline duels"] = "Отклонять дуэли"
L["Declines duel requests, except from friends and your guild."] = "Отклоняет вызовы на дуэль, кроме как от друзей и гильдии."
L["Vendors"] = "Торговцы"
L["Merchants"] = "Торговцы"
L["Sell grey items"] = "Продавать серые предметы"
L["Repairs all gear at merchants who can, when you can afford it. Hold Shift to skip."] = "Чинит все снаряжение у торговцев, которые это умеют, если хватает денег. Удерживайте Shift, чтобы пропустить."
L["Guild bank first"] = "Сначала банк гильдии"
L["When your guild rank may, the guild bank pays for repairs and your money covers the rest."] = "Если позволяет ваше звание, ремонт оплачивает банк гильдии, а остаток — ваши деньги."
L["Buy for the guide"] = "Покупать для гайда"
L["When the step asks you to buy something and the merchant sells it, buys what you still need after selling and repairing. Optional buys and anything over 50g are left to you. Hold Shift to skip."] = "Если шаг велит что-то купить, а торговец это продает, покупает недостающее после продажи и ремонта. Необязательные покупки и все дороже 50з остаются на вас. Удерживайте Shift, чтобы пропустить."
L["Trainers"] = "Учителя"
L["Experience"] = "Опыт"
L["XP tracker"] = "Счетчик опыта"
L["XP per hour, time, kills and quests to level, and level splits (/pole xp)."] = "Опыт в час, время, убийства и задания до уровня, а также время по уровням (/pole xp)."
L["Reset session"] = "Сбросить сеанс"
L["Start this session's XP per hour from zero."] = "Начать отсчет опыта в час за этот сеанс с нуля."
L["Mark what they target"] = "Помечать выбранные цели"
L["A new one each press"] = "Новая метка при каждом нажатии"
L["Icon on mobs"] = "Метка на противниках"
L["A new one each press skips the NPCs' icon and leaves a mob that has one as it is."] = "При смене метки пропускается метка, выбранная для NPC. Уже отмеченный противник сохраняет свою метку."
L["Icon on NPCs"] = "Метка на NPC"
L["A new one each press, so the last few NPCs keep theirs. Every press counts, even one that marks nothing."] = "При каждом нажатии выбирается новая метка, чтобы несколько последних NPC сохранили свои. Учитывается каждое нажатие, даже если никто не был отмечен."
L["Rare button"] = "Кнопка редкой цели"
L["Shows a button that targets a rare Polestar spotted nearby, until it dies or is out of sight. Bindable."] = "Показывает кнопку выбора замеченного рядом редкого противника, пока он не погибнет или не исчезнет из виду. Можно назначить клавишу."
L["Guide level on the XP bar"] = "Уровень гайда на полосе опыта"
L["A mark at the end of the game's XP bar with the level the guide wants you to reach before it moves on, and how many levels away that is when it is more than one."] = "Отметка в конце полосы опыта игры с уровнем, которого гайд просит достичь, прежде чем идти дальше, и сколько уровней до него, если больше одного."
L["Hearthstone"] = "Камень возвращения"
L["Set your home at the guide's inn"] = "Привязать дом к таверне гайда"
L["When the step sets your home and you talk to its innkeeper, binds your Hearthstone there. Never at another inn. Hold Shift to skip."] = "Когда шаг предписывает привязать дом и вы разговариваете с хозяином таверны, привязывает Камень возвращения там. Никогда — в другой таверне. Удерживайте Shift для пропуска."
L["Riding reminder"] = "Напоминание о верховой езде"
L["At level 40 and 60, if you have not learned riding yet, says the cost in chat (with any Honored discount) and points the arrow at your race's riding trainer when you can afford it. Warlocks and Alliance Paladins are sent to their free-mount quest NPC instead. Once per tier per character."] = "На 40-м и 60-м уровне, если вы еще не изучили верховую езду, сообщает в чате ее стоимость (с учетом скидки за уважение) и направляет стрелку к учителю верховой езды вашей расы, когда у вас хватает денег. Чернокнижников и паладинов Альянса вместо этого направляет к NPC, выдающему задание на бесплатный транспорт. Один раз на каждую ступень для каждого персонажа."
L["Hide the game's quest tracker"] = "Скрыть игровой список заданий"
L["Hides the game's tracker on the right of the screen, with its quests, achievements and professions, as Questie can. Not with the gamepad interface."] = "Скрывает игровой список отслеживания в правой части экрана с заданиями, достижениями и профессиями, как это умеет Questie. Не работает с интерфейсом для геймпада."
L["Reset"] = "Сбросить"
L["The item the current step uses, or a quest item it collects, glows in your bags (and in Baganator). An item a later step needs gets a lock, so you don't sell it."] = "Предмет, который использует текущий шаг, или собираемый предмет задания светится в сумках (и в Baganator). Предмет, нужный на одном из следующих шагов, получает замок, чтобы вы его не продали."
L["Offer gear upgrades"] = "Предлагать улучшения экипировки"
L["When gear from a kill, a chest or a merchant is an upgrade for your spec (with Gear advice on), the guide window offers to put it on. Nothing goes on until you press Wear it; Not this one stops it asking about that item."] = "Если экипировка с убитого противника, из сундука или от торговца лучше для вашей специализации (при включенных советах по экипировке), окно гайда предложит ее надеть. Ничего не надевается, пока вы не нажмете «Надеть»; «Не этот» отключает вопросы об этом предмете."
L["Sells Poor-quality items, and anything you marked as junk, when a merchant opens and prints the total. Never an item marked to keep or one a later step needs."] = "При открытии окна торговца продает предметы низкого качества и все, что вы пометили как хлам, и выводит итоговую сумму. Никогда не продает предметы, помеченные для хранения или нужные на следующих шагах."
L["Restock button"] = "Кнопка пополнения запасов"
L["At a merchant that sells what you are short of, a Restock button under its window buys up to the amounts below (this character's). Nothing is bought until you press it. Other items, such as reagents: /polestar restock <item> <amount>."] = "У торговца, который продает то, чего вам не хватает, кнопка «Пополнить» под его окном докупает до указанного ниже количества (для этого персонажа). Ничего не покупается, пока вы ее не нажмете. Другие предметы, например реагенты: /polestar restock <предмет> <количество>."
L["Keeps this many drinks in your bags. The merchant's best one for your level is bought."] = "Сколько напитков держать в сумках. Покупается лучший напиток торговца для вашего уровня."
L["Keeps this much food in your bags. The merchant's best one for your level is bought."] = "Сколько еды держать в сумках. Покупается лучшая еда торговца для вашего уровня."
L["Keeps this many arrows or shot for the bow, crossbow or gun you wear."] = "Сколько стрел или пуль держать для надетого лука, арбалета или ружья."
L["Bags"] = "Сумки"
L["When your bags are nearly full, a button shows the free slots and the cheapest junk in them, and while the step collects something the guide window says so too. Press twice to delete that junk: grey items, or common ones you marked as junk. Bindable."] = "Когда сумки почти заполнены, кнопка показывает свободные ячейки и самый дешевый хлам в них, а пока шаг требует что-то собирать, об этом сообщает и окно гайда. Нажмите дважды, чтобы удалить этот хлам: серые предметы или обычные, помеченные вами как хлам. Можно назначить клавишу."
L["Nearly full at"] = "Почти заполнены при"
L["%d slot"] = "%d ячейка"
L["%d slots"] = "%d ячеек"
L["How many free slots or fewer count as nearly full."] = "При каком числе свободных ячеек (или меньше) сумки считаются почти заполненными."
L["Junk and keep marks"] = "Пометки «хлам» и «хранить»"
L["Ctrl+Alt-click an item in your bags to mark it as junk, again to keep it, and again to clear it. Junk is sold with the grey items; a kept item is never sold or deleted."] = "Ctrl+Alt-щелчок по предмету в сумках помечает его как хлам, повторный — для хранения, еще один — снимает пометку. Хлам продается вместе с серыми предметами; хранимый предмет никогда не продается и не удаляется."
L["Step key talks and loots"] = "Клавиша шага: разговор и добыча"
L["Once the step key has targeted the step's NPC, the next press talks to it; on the corpse of the step's mob, it loots; in the step's quest window, it accepts or completes. Only out of combat, and only on the step the guide is at."] = "Когда клавиша шага выбрала целью NPC шага, следующее нажатие начинает с ним разговор; на трупе противника шага — забирает добычу; в окне задания шага — принимает или выполняет его. Только вне боя и только на шаге, где сейчас находится гайд."
L["Warn when out of breath"] = "Предупреждать о нехватке воздуха"
L["Under water, a red edge round the screen, a sound and a taskbar flash with 10 seconds of breath left, and again at 4."] = "Под водой: красная рамка по краю экрана, звук и мигание значка на панели задач, когда воздуха остается на 10 секунд, и еще раз на 4."
L["Pick what the step asks for"] = "Выбирать то, что требует шаг"
L["At the step's NPC, picks the chat option the guide names, or opens the goods or training the step needs. Only on the step the guide is at. Hold Shift to choose yourself."] = "У NPC шага выбирает вариант диалога, указанный в гайде, или открывает нужные шагу товары или обучение. Только на текущем шаге гайда. Удерживайте Shift, чтобы выбрать самому."
L["Picks the only option of NPCs without quests. Hold Shift to read it. Off, the game still skips some itself, Pick what the step asks for still picks the step's option, and flight masters follow Open the flight map."] = "Выбирает единственный вариант у NPC без заданий. Удерживайте Shift, чтобы прочитать. Если выключено, игра все равно пропускает некоторые сама, «Выбирать то, что требует шаг» все равно выбирает вариант шага, а распорядители полетов следуют настройке «Открывать карту полетов»."
L["Click objectives to target"] = "Выбор цели щелчком по задачам"
L["Clicking an objective row or NPC heading also targets its NPC outside combat, using the same marking settings as the Target button. This replaces your current target; a failed search clears it."] = "Щелчок по строке задачи или заголовку NPC вне боя также выбирает этого NPC целью, с теми же настройками меток, что и у кнопки цели. Текущая цель при этом заменяется; неудачный поиск сбрасывает её."
L["The target button and the step key put a raid icon on the mob and the NPC they target; out of combat, a press that finds neither clears your target. Pressing again never takes an icon off. In a party you don't lead, only a unit with no icon gets one; in a raid, only when you lead or assist."] = "Кнопка цели и клавиша шага ставят рейдовую метку на противника или НИП, которых выбирают целью; вне боя нажатие, не нашедшее ни того ни другого, сбрасывает вашу цель. Повторное нажатие никогда не снимает метку. В группе, где вы не лидер, метку получает только цель без метки; в рейде — только если вы лидер или помощник."
L["Ping what they target"] = "Отмечать пингом выбранную цель"
L["The target button and the step key ping the mob they target, so your group sees it behind rocks and buildings. Never in a raid unless you lead or assist. The rare buttons always ping."] = "Кнопка цели и клавиша шага отмечают пингом выбранного противника, чтобы группа видела его за скалами и зданиями. В рейде — только если вы лидер или помощник. Кнопки редкой цели отмечают всегда."
L["Show quest-starting loot"] = "Показывать добычу, начинающую задания"
L["When you loot an item that starts a quest you can take, it goes on the quest item button with a glow until you click it or take the quest. The step's own item comes first; several wait their turn, oldest first."] = "Когда вы получаете в добыче предмет, начинающий задание, которое можно взять, он появляется на кнопке предмета задания с подсветкой, пока вы не щелкнете по нему или не возьмете задание. Сначала идет предмет самого шага; несколько предметов ждут своей очереди, начиная с самого старого."
L["Track only dungeon quests in dungeons"] = "В подземельях отслеживать только их задания"
L["Inside a dungeon or raid, the game's quest tracker and Polestar's quest markers show only that instance's quests. The quests you were tracking come back when you leave, even after a reload inside."] = "В подземелье или рейде игровой список заданий и маркеры заданий Polestar показывают только задания этого подземелья. Отслеживаемые задания вернутся, когда вы выйдете, даже после перезагрузки интерфейса внутри."
L["New spells at level-up"] = "Новые заклинания при повышении уровня"
L["When you level up, a card on the guide window shows the class spells you can now train, what they cost together and the nearest class trainer, with a button for the arrow. Not in combat or instances, and not on levels with nothing new."] = "При повышении уровня карточка в окне гайда показывает классовые заклинания, которые теперь можно изучить, их общую стоимость и ближайшего учителя классовых навыков, с кнопкой для стрелки. Не в бою и не в подземельях, и не на уровнях без новых заклинаний."
L["Old ranks on your bars"] = "Старые ранги на панелях"
L["After training and at login, says which spells on your action bars are a lower rank than the one in your spellbook, with a button that puts the highest rank in the same buttons (out of combat). Macros and items are never touched. Right-click a spell on the card to keep it at its rank; a lower rank you put on a bar yourself is kept too."] = "После обучения и при входе в игру сообщает, какие заклинания на панелях команд ниже рангом, чем в книге заклинаний, с кнопкой, которая ставит высший ранг на те же кнопки (вне боя). Макросы и предметы не затрагиваются. Щелкните правой кнопкой по заклинанию на карточке, чтобы оставить его ранг; более низкий ранг, который вы сами поставили на панель, тоже сохраняется."
L["Forget kept ranks"] = "Забыть оставленные ранги"
L["Lists the spells you kept at a lower rank again."] = "Снова показывает заклинания, которые вы оставили в более низком ранге."
L["Boosted Rest status"] = "Статус «Улучшенного отдыха»"
L["How long the campfire's Boosted Rest lasts and the Cozy Sleeping Bag's cooldown, under the guide window's XP line; your party's Boosted Rest in the party panel."] = "Сколько длится «Улучшенный отдых» от костра и время восстановления «Уютного спального мешка» — под строкой опыта в окне гайда; «Улучшенный отдых» вашей группы — на панели группы."
L["Take the marked flight"] = "Лететь в отмеченный пункт"
L["When the flight map opens, flies to the marked destination. Hold Shift at the flight master to choose yourself."] = "Когда открывается карта полетов, отправляет в отмеченный пункт. Удерживайте Shift у распорядителя полетов, чтобы выбрать самому."
