-- Dungeons/Dungeons.lua
L["Dungeon quests, bosses and entrances"] = "Задания, боссы и входы подземелий"
L["Dungeons"] = "Подземелья"
L["A page per dungeon and raid: every quest with where to get it, its chain and rewards, the bosses and the entrance."] = "Страница для каждого подземелья и рейда: все задания с местом получения, цепочкой и наградами, боссы и вход."
L["Kill %d %s"] = "Убить: %2$s (%1$d)"
L["Collect %s"] = "Собрать: %s"
L["Collect %d %s"] = "Собрать: %2$s (%1$d)"
L["Use %s"] = "Использовать: %s"
L["Dungeons in leveling guides"] = "Подземелья в гайдах по прокачке"
L["Off: the guide skips this group quest and keeps to the solo route. Until you choose, it asks when it gets there."] = "Если выключено, гайд пропускает это групповое задание и придерживается одиночного маршрута. Пока вы не сделаете выбор, гайд будет спрашивать, когда дойдет до него."
L["Group quests"] = "Групповые задания"
L["Group quests in leveling guides"] = "Групповые задания в гайдах по прокачке"
L["Tell me when a dungeon opens up"] = "Сообщать, когда открывается подземелье"
L["When a level-up opens a dungeon's quests to this character, a card on the guide window says so, once per dungeon, with a button that picks up its quests in a new tab."] = "Когда новый уровень открывает этому персонажу задания подземелья, в окне гайда появляется карточка (один раз для каждого подземелья) с кнопкой, которая открывает сбор его заданий в новой вкладке."
L["Entrance in Horde territory (outside the Undercity)"] = "Вход на территории Орды (у Подгорода)"
L["Entrance in Alliance territory (in Ironforge)"] = "Вход на территории Альянса (в Стальгорне)"
L["Entrance in Horde territory (in Orgrimmar)"] = "Вход на территории Орды (в Оргриммаре)"
L["Entrance in Alliance territory (in Stormwind)"] = "Вход на территории Альянса (в Штормграде)"
L["Leveling guides take you through this dungeon where they have steps for it. Off: they keep to the solo route. More dungeons join this list as they are added to the guides' route."] = "Гайды по прокачке проводят вас через это подземелье, если в них есть шаги для него. Если выключено, они придерживаются одиночного маршрута. Новые подземелья появятся в этом списке, когда их добавят в маршрут гайдов."
L["Speak with %s"] = "Поговорить: %s"
