-- Dungeons/Pickup.lua
L["Quest giver"] = "Дающий задание"
L["In your log already: %s"] = "Уже в журнале: %s"
L["After the run: choose Hand in the quests at the end of this guide or on the dungeon's page."] = "После прохождения: выберите «Сдать задания» в конце этого руководства или на странице подземелья."
L["%s: pick up the quests"] = "%s: взять задания"
L["Pick up the quests from level %d"] = "Взять задания с уровня %d"
L["Pick up the quests (%d now · %d at level %d)"] = "Взять задания (%d сейчас · %d на уровне %d)"
L["Pick up the quests (%d now · %d from level %d)"] = "Взять задания (%d сейчас · %d с уровня %d)"
L["%s: level %d, needs %s first"] = "%s: уровень %d, сначала нужно %s"
L["%s: level %d"] = "%s: уровень %d"
L["Comes back at level %d: %s"] = "Вернётся на уровне %d: %s"
L["Level %d: you can take %s now. Its giver is marked on your map; pick up the quests again to add it to the guide."] = "Уровень %d: теперь можно взять %s. Тот, кто его выдаёт, отмечен на карте; возьмите задания снова, чтобы добавить его в гайд."
L["Leads to %s."] = "Ведет к %s."
L["Needed for %s."] = "Нужно для %s."
L["Prerequisite quests: %d of %d steps, about %s."] = "Предварительные задания: %d из %d шагов, примерно %s."

