L["Mark here"] = "Отметить здесь"
L["Cancel"] = "Отмена"
L["Walk to where the step should have sent you: the NPC, the object or the mobs as you found them. Then press Mark here. Your report is kept while you walk."] = "Дойдите до места, куда должен был отправить вас шаг: к NPC, объекту или существам там, где вы их нашли. Затем нажмите «Отметить здесь». Ваш отчет сохранится, пока вы идете."
L["Clear mark"] = "Снять отметку"
L["Report it on Discord"] = "Сообщить в Discord"
L["1. Press Copy report, then Ctrl+C (Cmd+C on a Mac).\n2. In the Polestar Discord, open #bugs and press New Post. Not in it yet? Get the invite.\n3. Paste the report, give it a short title and post it. A bot files it for the developers and tells you in your thread when it's fixed."] = "1. Нажмите «Копировать отчет», затем Ctrl+C (Cmd+C на Mac).\n2. На сервере Polestar в Discord откройте #bugs и нажмите New Post. Вас еще нет на сервере? Получите приглашение.\n3. Вставьте отчет, дайте ему короткое название и опубликуйте. Бот передаст его разработчикам и сообщит в вашей ветке, когда ошибку исправят."
L["Have a GitHub account? Open the issue there with everything filled in."] = "Есть аккаунт на GitHub? Создайте там issue, где все уже будет заполнено."
