L["A community addon is a separate addon with someone else's guides for Polestar. It is not part of Polestar, and its guides are not Polestar's own routes."] = "Аддон сообщества — отдельный аддон с чужими гайдами для Polestar. Он не входит в Polestar, и его гайды — не маршруты Polestar."
L["Get a community addon from wherever its author publishes it and install it like any addon, then restart the game. Its guides appear in the guide menu under Community guides, with the author's name. The switch on its row above turns it on or off."] = "Скачайте аддон сообщества там, где его публикует автор, установите как любой аддон и перезапустите игру. Его гайды появятся в меню гайдов в разделе «Гайды сообщества» с именем автора. Переключатель в его строке выше включает и выключает его."
L["Each community addon is made and supported by its author: report its problems to them, not to Polestar. It is an addon like any other, so install community addons from authors you trust."] = "Каждый аддон сообщества создает и поддерживает его автор: сообщайте о проблемах ему, а не Polestar. Это обычный аддон, поэтому ставьте аддоны сообщества от авторов, которым доверяете."
L["Anyone can make a community addon with Polestar's own tools."] = "Любой может создать аддон сообщества с помощью инструментов Polestar."
L["Community guides, explained"] = "Гайды сообщества: подробно"
L["Installed"] = "Установлены"
L["Read more:"] = "Подробнее:"
L["Read more: docs/GUIDE_PACKS.md in Polestar's source"] = "Подробнее: docs/GUIDE_PACKS.md в исходниках Polestar"
L["Turn on and reload"] = "Включить и перезагрузить"
L["Polestar Guides is turned off in the AddOns list, so Polestar has no guides to show. Turn it on for all your characters and reload?"] = "Polestar Guides отключен в списке модификаций, поэтому у Polestar нет гайдов для показа. Включить его для всех ваших персонажей и перезагрузить?"

-- UI/Options.lua
L["Recorder"] = "Запись"
L["About"] = "О Polestar"
L["%d px"] = "%d пикс."
L["Window"] = "Окно"
