L["Put the guide window back in its corner."] = "Вернуть окно гайда в его угол."
L["Arrow"] = "Стрелка"
L["Show arrow"] = "Показывать стрелку"
L["Arrival time"] = "Время прибытия"
L["Estimated time under the distance."] = "Примерное время под расстоянием."
L["Distances"] = "Расстояния"
L["How the arrow, map tooltips, rares and the death helper show distances."] = "Как стрелка, подсказки карты, редкие и помощник при смерти показывают расстояния."
L["Yards (the game's unit)"] = "Ярды (единица игры)"
L["Metres"] = "Метры"
L["Arrival sound"] = "Звук прибытия"
L["A soft chime when you reach a waypoint."] = "Тихий звон при достижении путевой точки."
L["Reset arrow position"] = "Сбросить положение стрелки"
L["Back to the top of the screen. Drag the arrow to move it."] = "Вернуть наверх экрана. Перетащите стрелку, чтобы переместить."
L["Plan travel routes"] = "Планировать маршруты"
L["Flights, boats and your hearthstone when they are faster. Off: the arrow points straight at the goal."] = "Полеты, корабли и камень возвращения, если так быстрее. Выкл.: стрелка указывает прямо на цель."
L["Walk real paths"] = "Реальные пути"
L["The arrow follows paths on the ground around cliffs, water and walls, on Polestar's walking maps, with Shortest Path Forever's router by Cillian Berragan. Off: it points straight at each stop."] = "Стрелка ведет по тропам в обход скал, воды и стен по картам Polestar с маршрутизатором Shortest Path Forever от Cillian Berragan. Выкл.: указывает прямо на каждую точку."
L["Route lines"] = "Линии маршрута"
L["Class teleports"] = "Классовые телепорты"
L["Routes may start with a Teleport spell you know (a mage's city teleports, a druid's Moonglade) when it is faster. A city teleport needs a Rune of Teleportation in your bags."] = "Маршрут может начинаться с известного вам заклинания телепорта (городские телепорты мага, Лунная поляна друида), если так быстрее. Для телепорта в город нужна руна телепортации в сумках."
L["Share boat times"] = "Делиться расписанием кораблей"
L["Riding a boat, zeppelin, tram or lift times it; your guild and group get those times and you get theirs, so the arrow can say when the next one leaves."] = "Поездка на корабле, дирижабле, поезде или подъемнике засекает время; ваша гильдия и группа получают эти данные, а вы — их, чтобы стрелка подсказывала отправление следующего."
L["Blizzard waypoint"] = "Точка Blizzard"
L["Also set the game's own map pin and tracking."] = "Также ставить метку и отслеживание самой игры."
L["Mirror to TomTom"] = "Дублировать в TomTom"
L["Adds the target as a TomTom waypoint when TomTom is loaded."] = "Добавляет цель как путевую точку TomTom, если TomTom загружен."
L["Use TomTom's arrow"] = "Стрелка TomTom"
L["Hides Polestar's arrow in favour of TomTom's, except on the way to another continent, where TomTom's arrow cannot point."] = "Скрывает стрелку Polestar в пользу стрелки TomTom, кроме пути на другой континент: туда стрелка TomTom указать не может."
L["Automation"] = "Автоматизация"
L["Accept guide quests"] = "Принимать задания гайда"
L["Only quests in the next steps of your open guides. Hold Shift to skip."] = "Только задания из ближайших шагов открытых гайдов. Shift — пропустить."
L["Turn in guide quests"] = "Сдавать задания гайда"
L["Never picks between rewards. Hold Shift to skip."] = "Никогда не выбирает награду. Shift — пропустить."
L["Warn about missable quests"] = "Предупреждать о пропускаемых заданиях"
L["Before you take a quest that closes another for good, says which in chat and leaves the accept to you."] = "Перед заданием, которое навсегда закроет другое, пишет в чат какое и оставляет принятие вам."
L["Skip grey quests"] = "Пропускать серые задания"
L["Leaves out grey quests and their turn-ins, unless a later quest needs them first."] = "Не включает серые задания и их сдачу, если они не нужны для последующего задания."
L["Pick a guide for me"] = "Выбирать гайд за меня"
L["Where to level next"] = "Где качаться дальше"
