L["Flat"] = "Плоская"
L["Arrow colour"] = "Цвет стрелки"
L["The arrow on its way; the target's pin on the maps and the route's stops wear it too. Right-click to go back to the accent."] = "Стрелка в пути; этот же цвет у метки цели на картах и у точек маршрута. ПКМ — вернуть цвет акцента."
L["Jade"] = "Нефрит"
L["What Polestar draws on the world map and the minimap. Quest, rare and travel icons start off."] = "Что Polestar рисует на карте и мини-карте. Значки заданий, редких и перемещений изначально выключены."
L["Guide pins on the world map"] = "Метки гайда на карте"
L["The arrow's target, the stops of its travel route, the step's other goals, the areas their mobs and objects spawn in, and the route lines."] = "Цель стрелки, точки ее маршрута, другие цели шага, области появления их существ и объектов, а также линии маршрута."
L["Guide pin on the minimap"] = "Метка гайда на мини-карте"
L["The arrow's target, the areas it spawns in, and the route line."] = "Цель стрелки, области ее появления и линия маршрута."
L["Trail dots along the travel route"] = "Точки следа вдоль маршрута"
L["Moving dots from you to the target on the world map and the minimap, along the travel route, while route lines are off."] = "Движущиеся точки от вас к цели на карте и мини-карте вдоль маршрута, пока линии маршрута выключены."
L["Rares and treasures"] = "Редкие и сокровища"
L["Quest information, rewards and gear advice, and the quest buttons."] = "Сведения о заданиях, награды, советы по экипировке и кнопки заданий."
L["Talents"] = "Таланты"
L["Talent plan"] = "План талантов"
L["Lookup, the dungeon journal and rares: finding things in the world."] = "Поиск, журнал подземелий и редкие: как найти что-то в мире."
L["When a rare shows up"] = "Когда появляется редкий"
L["How rares are noticed"] = "Как замечать редких"
L["Status"] = "Состояние"
L["Actions"] = "Действия"
L["Start recording"] = "Начать запись"
L["Write quests, routes and world data for guide authors. Off until you start it."] = "Записывать задания, маршруты и данные мира для авторов гайдов. Выключено, пока не начнете."
L["Print status"] = "Вывести состояние"
L["The Polestar Recorder addon is not loaded. Enable it in the AddOns list on the character screen to record your play for guide authoring."] = "Аддон Polestar Recorder не загружен. Включите его в списке модификаций на экране выбора персонажа, чтобы записывать игру для создания гайдов."
L["Recording"] = "Идет запись"
L["Stop recording"] = "Остановить запись"
L["Nothing more is written until you start it again."] = "Ничего не записывается, пока не начнете снова."
L["Leveling guides for World of Warcraft: Forever."] = "Гайды по прокачке для World of Warcraft: Forever."
L["This translation was made with AI. Help improve it on Discord."] = "Этот перевод сделан с помощью ИИ. Помогите улучшить его в Discord."
L["Why Polestar"] = "Зачем Polestar"
L["Leveling guides have become a business: the best routes sit behind subscriptions and paywalls. Polestar goes the other way. It is free, open source under the GPL-3.0, and built by the community that plays it."] = "Гайды по прокачке стали бизнесом: лучшие маршруты спрятаны за подписками и платным доступом. Polestar идет другим путем. Он бесплатный, с открытым кодом под GPL-3.0 и создается сообществом, которое в него играет."
L["Polestar doesn't claim to be the fastest guide, or the smoothest. It is a free alternative, and it gets better with time."] = "Polestar не претендует на звание самого быстрого или самого гладкого гайда. Это бесплатная альтернатива, и со временем она становится лучше."
L["Anyone can read the code, fix a step, sharpen a route or write a new guide, and contributions are welcome. The GPL keeps it that way: every copy and every fork stays open."] = "Любой может читать код, исправить шаг, улучшить маршрут или написать новый гайд — вклад приветствуется. GPL сохраняет это: каждая копия и каждый форк остаются открытыми."
L["It is young and still in beta, so expect the odd wrong step, waypoint or quest. Every report and every fix tunes it, and together we'll get it where it should be."] = "Он молод и еще в бете, так что ждите иногда неверных шагов, путевых точек или заданий. Каждый отчет и каждое исправление его улучшают, и вместе мы доведем его до ума."
L["Open source and free is the future."] = "Открытый и бесплатный код — это будущее."
L["show or hide the guide window"] = "показать или скрыть окно гайда"
L["choose a guide"] = "выбрать гайд"
L["move through steps"] = "переход по шагам"
L["report a problem with a step on the Polestar Discord"] = "сообщить о проблеме с шагом в Discord Polestar"
