L["With Grow upward, put the tabs and the step bar at the bottom edge, next to where the window is pinned."] = "При росте окна вверх вкладки и панель шагов размещаются у нижнего края, рядом с точкой закрепления окна."
L["Close offers the guide skips"] = "Закрывать предложения, которые гайд пропускает"
L["After Polestar accepts or turns in a quest, closes the quest window the NPC opens next when the guide skips its quests. Hold Shift to keep it open."] = "Когда Polestar принимает или сдаёт задание, закрывает окно задания, которое NPC открывает следующим, если гайд его пропускает. Удерживайте Shift, чтобы оставить открытым."
L["Elite and escort quests the guides mark for a group. Ask at each, or answer them all: with a group (a party levelling together) or skip them (solo). Discovery, Group quests changes one."] = "Элитные задания и задания на сопровождение, которые гайды отмечают как групповые. Спрашивать о каждом или ответить сразу за все: выполнять в группе (если вы качаетесь вместе в группе) или пропускать (в одиночку). Изменить решение по отдельному заданию можно в разделе «Обнаружение», «Групповые задания»."
L["Ask me at each"] = "Спрашивать о каждом"
L["Do them with a group"] = "Выполнять в группе"
L["Skip them"] = "Пропускать"
L["Offer class quests"] = "Предлагать классовые задания"
L["When one of your class's Class guides opens (your level, its first quest), the guide window offers to open it in a tab."] = "Когда становится доступен один из классовых гайдов для вашего класса (подходит уровень, доступно его первое задание), окно гайда предлагает открыть его во вкладке."
L["Celebrating the supporters, contributors and bug reporters behind Polestar."] = "Чествуем тех, кто поддерживает, развивает и тестирует Polestar."
L["Position trails, marks and the list of spots to walk, in a small window."] = "Следы позиции, метки и список мест для прохождения в маленьком окне."
L["Reset guide progress?"] = "Сбросить прогресс гайда?"
L["Reset progress"] = "Сбросить прогресс"
L["Reset all settings?"] = "Сбросить все настройки?"
L["Reset all"] = "Сбросить все"
L["Every Polestar setting goes back to its default. Your guides and progress are kept."] = "Все настройки Polestar вернутся к значениям по умолчанию. Ваши гайды и прогресс сохранятся."
L["Preview"] = "Предпросмотр"
L["Live"] = "Вживую"
L["Rot Hide Mongrel"] = "Паршивая дворняга"
L["Brill"] = "Брилл"
L["Run"] = "Бег"
L["Reset this page?"] = "Сбросить эту страницу?"
L["Every setting on %s goes back to its default."] = "Все настройки на странице «%s» вернутся к значениям по умолчанию."
L["Waiting to upload"] = "Ожидает отправки"
L["Chunks the Polestar Uploader has not sent yet."] = "Фрагменты, которые Polestar Uploader еще не отправил."
L["Stored"] = "Сохранено"
L["Last uploaded chunk"] = "Последний отправленный фрагмент"
L["Recordings"] = "Записи"
L["Chunks waiting, the last upload and the install id, in chat."] = "Ожидающие фрагменты, последняя отправка и ID установки — в чат."
L["Characters"] = "Персонажи"
L["Icon pack"] = "Набор значков"
L["The medallion under every mark on the world map and the minimap. The skin's: Polestar's, Halo's, or Hearth's for Hearth and the game's own looks. Glyphs only: no medallion."] = "Медальон под каждой меткой на карте и мини-карте. «Значки облика»: медальон Polestar, «Ореола» или «Очага» (для «Очага» и стандартного вида игры). «Только символы»: без медальона."
L["The skin's icons"] = "Значки облика"
L["Glyphs only"] = "Только символы"
L["Use deathskips"] = "Использовать смерть для сокращения пути"
L["Where dying on purpose and taking the Spirit Healer's resurrection gets you there sooner, the guide shows a step for it. It costs durability and, from level 11, resurrection sickness. Always off on Hardcore characters."] = "Если умереть намеренно и воскреснуть у Целителя душ быстрее, гайд покажет для этого шаг. Это снижает прочность, а с 11-го уровня вызывает слабость после воскрешения. Всегда отключено для персонажей Hardcore."
L["Text size"] = "Размер текста"
L["The size of Polestar's text, apart from the window scale. Changes at once. Right-click to reset."] = "Размер текста Polestar независимо от масштаба окна. Меняется сразу. Щелкните правой кнопкой мыши для сброса."
L["Numbered pins for the steps ahead"] = "Нумерованные метки следующих шагов"
L["A small pin with its step number where each of the next steps takes you, fainter the further ahead. As many as Up next shows, else five."] = "Маленькая метка с номером шага там, куда ведет каждый из следующих шагов; чем дальше шаг, тем бледнее метка. Столько, сколько показывает «Далее», иначе пять."
L["When a leveling guide ends"] = "Когда гайд прокачки заканчивается"
L["Ask me: a window says the guide is done and offers the next one. Continue automatically: the next guide loads in the same tab."] = "Спросить: окно сообщит, что гайд пройден, и предложит следующий. Продолжать автоматически: следующий гайд загрузится в той же вкладке."
L["Ask me"] = "Спросить"
L["Continue automatically"] = "Продолжать автоматически"
L["%d KiB"] = "%d КиБ"
L["%.1f MB"] = "%.1f МБ"
L["%d KB"] = "%d КБ"
L["Show the whole step"] = "Показывать весь шаг"
L["Every goal of the step at once, finished ones kept, instead of one person at a time with the others on one line each."] = "Все цели шага сразу, вместе с выполненными, вместо одного персонажа за раз и остальных по строке на каждого."
L["Maximum height"] = "Максимальная высота"
L["How tall the window may grow, as a share of the screen. A longer step scrolls."] = "Насколько высоким может стать окно, в доле экрана. Более длинный шаг прокручивается."
L["Hide the arrow with the guide"] = "Скрывать стрелку вместе с гайдом"
L["When the guide window is hidden, hide the arrow too."] = "Когда окно гайда скрыто, скрывать и стрелку."
L["Small conveniences: questing, travel, invitations, merchants, bags, trackers and the map."] = "Мелкие удобства: задания, перемещения, приглашения, торговцы, сумки, трекеры и карта."
L["Did you mean:"] = "Возможно, вы искали:"
L["In dungeons and battlegrounds"] = "В подземельях и на полях боя"
L["Wait for Spoken"] = "Ждать Spoken"
L["Waits 200 ms before each automatic quest accept, turn-in and reward pick, so Spoken has time to notice the window and read it."] = "Пауза 200 мс перед каждым автоматическим принятием, сдачей задания и выбором награды, чтобы Spoken успел заметить окно и прочитать его."
L["How close"] = "Насколько близко"
L["Include nearby hand-ins"] = "Включая сдачу заданий рядом"
L["Dynamic Questing"] = "Динамические задания"
L["Sound for a new suggestion"] = "Звук новой подсказки"
L["Suggests objectives from later steps when you are near them, from your quest log and what is around you. They show under the step in a \"While you're here\" panel: click one to point the arrow there; right-click to dismiss it around here (dismissed twice, it stays away for the zone)."] = "Предлагает цели из следующих шагов, когда вы рядом с ними, — по вашему журналу заданий и окружению. Они показываются под шагом на панели «Пока вы здесь»: щелчок направляет туда стрелку; ПКМ скрывает подсказку в этих местах (скрытая дважды, она не появится до конца зоны)."
L["A soft chime for each new suggestion (once when several come together), at the game's sound effects volume."] = "Тихий звон для каждой новой подсказки (один раз, если их несколько сразу), с громкостью звуковых эффектов игры."
L["What's new"] = "Что нового"
L["When you abandon a guide quest"] = "Если вы отказались от задания гайда"
L["Always go back for it"] = "Всегда возвращаться за ним"
L["Always skip it"] = "Всегда пропускать"
L["Ask me: the guide stays on its step, leads you back to the quest giver, and the guide window asks. Or always go back for the quest, or always skip it and the quests that follow from it; chat says which."] = "Спрашивать: гайд остается на шаге, ведет вас обратно к тому, кто дает задание, и окно гайда спрашивает. Либо всегда возвращаться за заданием, либо всегда пропускать его и следующие из него задания; в чате будет сказано, что выбрано."
L["Also a quest ready to hand in whose NPC is a little out of your way, when the guide hands it in later."] = "А также задание, готовое к сдаче, если его НИП немного в стороне, а гайд сдает его позже."
L["Hand-ins: how far out of your way"] = "Сдача: насколько в стороне"
L["The seconds of extra walking a hand-in may cost, to its NPC and back on your way. One in the town you are in always shows; 0 keeps to those."] = "Сколько секунд лишнего пути может стоить сдача: до НИП и обратно на маршрут. Сдача в городе, где вы находитесь, показывается всегда; 0 — только такие."
L["Route line on the minimap"] = "Линия маршрута на миникарте"
L["The way to the goal on the minimap. Off keeps the guide pin there and the line on the world map. Its colour, opacity and size: the gear beside Guide > Arrow & routes > Route lines."] = "Путь к цели на миникарте. Если выключено, на миникарте остается метка гайда, а линия — на карте мира. Цвет, непрозрачность и размер: шестеренка рядом с Гайд > Стрелка и маршруты > Линии маршрута."
L["Show and hide"] = "Показ и скрытие"
L["Floating button"] = "Плавающая кнопка"
L["Step key targets their mobs"] = "Клавиша шага выбирает их противников"
L["The step key also targets the mobs of the suggestions, nearest first, after the current step's own. It changes only out of combat."] = "Клавиша шага также выбирает целью противников из подсказок, ближайших первыми, после противников текущего шага. Цель меняется только вне боя."
L["Mark quests new in Forever"] = "Отмечать задания, новые в Forever"
L["A small infinity mark beside the name of a quest Forever added, in the guide, While you're here, the Codex and quest tooltips."] = "Маленький значок бесконечности рядом с названием задания, добавленного Forever, — в гайде, «Пока вы здесь», Codex и подсказках заданий."
L["The way to the goal on the world map and the minimap: a line or dots where you walk, lines where you fly, sail or ride, the legs after this one fainter. Drawn as Shortest Path Forever by Cillian Berragan draws them."] = "Путь к цели на карте мира и миникарте: линия или точки — где идти пешком, линии — где лететь, плыть или ехать; последующие участки бледнее. Рисуются так же, как в Shortest Path Forever от Cillian Berragan."
L["How the route lines are drawn: one solid line, Polestar's dots, or sparkles that drift along the way to the goal (dots while Reduce motion is on)."] = "Как рисуются линии маршрута: сплошная линия, точки Polestar или искры, плывущие по пути к цели (точки при включенном «Меньше анимации»)."
L["A Polestar button in the game menu (Esc) that opens the guide menu."] = "Кнопка Polestar в игровом меню (Esc), открывающая меню гайда."
L["Backing"] = "Подложка"
L["Soft"] = "Мягкая"
L["Dark"] = "Тёмная"
L["With Transparent, the tabs and the step bar stay on screen instead of only under the cursor."] = "В прозрачном стиле вкладки и панель шага остаются на экране, а не только под курсором."
L["With Transparent: Soft lays a light shade behind each line of text, Dark a dark backing behind the whole window. Off: the outlined text alone on the world."] = "В стиле «Прозрачный»: «Мягкая» кладет легкую тень под каждую строку текста, «Тёмная» – темную подложку под все окно. «Выкл.»: только текст с обводкой поверх мира."
L["Tell me when a newer Polestar is out"] = "Сообщать о выходе новой версии Polestar"
L["At login, a card on the guide window says a newer Polestar is out and how to update; Got it keeps it away for a day. A line in the guide window stays until you update. Two or more updates behind, both show even with this off (the card at most once a day)."] = "При входе в игру карточка в окне гайда сообщает, что вышел новый Polestar, и как обновиться; «Понятно» скрывает ее на сутки. Строка в окне гайда остается, пока вы не обновитесь. Если вы отстали на два обновления или больше, обе показываются даже при выключенной настройке (карточка — не чаще раза в сутки)."
L["What the window, its buttons and alerts do in dungeons, raids, battlegrounds and arenas. Guide window in the minimap button's menu, the key binding or /polestar opens it there until you leave."] = "Что делают окно, его кнопки и оповещения в подземельях, рейдах, на полях боя и аренах. «Окно гайда» в меню кнопки у миникарты, назначенная клавиша или /polestar открывает его там до вашего выхода."
L["A small Polestar button you can put anywhere on the screen. Click to hide or show Polestar, right-click for a menu, drag to move it. It hides with the window in combat and in dungeons when those are set to Hide."] = "Маленькая кнопка Polestar, которую можно разместить в любом месте экрана. Щелчок скрывает или показывает Polestar, ПКМ — меню, перетаскивание перемещает её. Она скрывается вместе с окном в бою и в подземельях, если для них выбрано «Скрыть»."
L["Hiding Polestar leaves the arrow, its travel button and its arrival sound. This character only."] = "При скрытии Polestar остаются стрелка, её кнопка пути и звук прибытия. Только для этого персонажа."
L["How near the middle of its spawn area you must be for a suggestion to show. It goes again a little further out."] = "Насколько близко к центру области появления нужно быть, чтобы показать подсказку. Она исчезает чуть дальше."
L["Flight paths you pass"] = "Маршруты полета по пути"
L["Also a friendly flight master near you whose flight path you haven't learned yet. Learning it ticks the guide's later step for it too."] = "Также дружественный распорядитель полетов рядом с вами, чей маршрут полета вы еще не изучили. Если изучить его, более поздний шаг гайда для него тоже будет отмечен."
L["Detour captions"] = "Подписи об обходе"
L["Under a walk in the journey, say when it goes round a town of the other faction: \"Detour around Southshore\". It only says so: the route and the arrow stay as they are."] = "Под пешим участком пути пишет, когда он обходит город другой фракции: «Обход: Южнобережье». Только пишет: маршрут и стрелка не меняются."
L["Manual check-offs and skips, current guide, from your last quest progress on."] = "Ручные отметки и пропуски, текущий гайд, начиная с последнего продвижения по заданиям."
L["Your manual check-offs and skipped steps in %s are cleared from your last quest progress on. Quests you have done stay done, and the guide stays where they put you."] = "Ваши ручные отметки и пропущенные шаги в гайде %s будут удалены начиная с последнего продвижения по заданиям. Выполненные задания останутся выполненными, а гайд останется там, куда они вас привели."
L["Your manual check-offs and skipped steps in the current guide are cleared from your last quest progress on. Quests you have done stay done, and the guide stays where they put you."] = "Ваши ручные отметки и пропущенные шаги в текущем гайде будут удалены начиная с последнего продвижения по заданиям. Выполненные задания останутся выполненными, а гайд останется там, куда они вас привели."
