-- Rares/Options.lua
L["1 minute"] = "1 минута"
L["%d minutes"] = "%d мин"
L["%d s"] = "%d с"
L["Watch for rare NPCs and treasures and keep when you last met them (/pole rares). Their map pins are under Map, off by default."] = "Следить за редкими NPC и сокровищами и запоминать, когда вы их встречали (/pole rares). Их метки на карте — в разделе «Карта», по умолчанию выключены."
L["Alert for rares"] = "Оповещать о редких"
L["A card with its name, level and distance, and a waypoint to it."] = "Карточка с именем, уровнем и расстоянием, плюс путевая точка к нему."
L["Alert for treasures"] = "Оповещать о сокровищах"
L["Treasures the client marks on the minimap."] = "Сокровища, отмеченные игрой на мини-карте."
L["Once per rare every"] = "Не чаще раза на редкого за"
L["The same rare stays quiet this long after an alert."] = "После оповещения этот редкий молчит столько времени."
L["Alert stays for"] = "Оповещение держится"
L["Hovering the alert holds it."] = "Наведение курсора удерживает оповещение."
L["Alert during combat"] = "Оповещать в бою"
L["Off: an alert waits for the fight to end, if the rare was seen in the last minute."] = "Выкл.: оповещение ждет конца боя, если редкий был замечен в последнюю минуту."
L["Play a sound"] = "Звук оповещения"
L["One sound with each alert."] = "Один звук с каждым оповещением."
L["Sound"] = "Звук"
L["Played through the Master channel."] = "Воспроизводится через основной канал."
L["See where the alert sits; drag it to move it."] = "Показать место оповещения; перетащите, чтобы сдвинуть."
L["Rares and treasures the client marks on the minimap (vignettes), with their exact distance."] = "Редкие и сокровища, отмеченные игрой на мини-карте, с точным расстоянием."
L["Nameplates"] = "Индикаторы здоровья"
L["A rare's nameplate coming into view. Needs enemy nameplates on."] = "Появление индикатора редкого. Нужны включенные индикаторы противников."
L["Your target"] = "Ваша цель"
L["Targeting a rare."] = "Редкий взят в цель."
L["Under the cursor"] = "Под курсором"
L["Pointing at a rare in the world."] = "Курсор наведен на редкого в мире."
L["Rares on the world map"] = "Редкие на карте"
L["Every known spawn point. Click one to see it in Rares; Shift-click for a waypoint."] = "Все известные места появления. Щелчок — показать в «Редких», Shift-щелчок — путевая точка."
L["Treasures on the world map"] = "Сокровища на карте"
