-- Talents/Builds.lua
L["Holy"] = "Свет"
L["Protection"] = "Защита"
L["Level as Retribution (quickest solo, with a two-hander and Seal of Command) or Protection (safe group pulls, dungeon-tank ready). Holy suits raids; it can level through its melee build, more slowly, if you want to heal dungeons on the way."] = "Качайтесь в Воздаянии (быстрее всего в одиночку, с двуручным оружием и Печатью повеления) или в Защите (безопасные групповые пулы, готовность танковать подземелья). Свет подходит для рейдов; в нем можно качаться через ближний бой, но медленнее, если хотите по пути лечить в подземельях."
L["Start with Divine Intellect: more mana means you can melee and still cover your own (or a group's) healing."] = "Начните с Божественного интеллекта: больше маны — значит, можно драться в ближнем бою и при этом лечить себя (или группу)."
L["Improved Seals raises every seal and Judgement here, which is where Holy's leveling damage comes from."] = "Улучшенные печати усиливают здесь все печати и Правосудие — отсюда и берется урон Света при прокачке."
L["Reverence keeps a trickle of regen going while casting; three ranks unlock Illumination."] = "Почтение поддерживает небольшое восполнение маны во время произнесения заклинаний; три ранга открывают Озарение."
L["Illumination refunds mana on critical heals and is the heart of Holy's staying power."] = "Озарение возвращает ману при критических исцелениях и является основой выносливости Света."
L["Holy Shock is a talent on Forever: an instant heal or Holy hit, handy for emergencies and for pulling."] = "Шок небес на Forever — это талант: мгновенное исцеление или удар Светом, полезный в экстренных случаях и для пулла."
L["Holy Power raises Holy Shock's crit chance, feeding Illumination and Infusion of Light."] = "Сила Света повышает шанс критического эффекта Шока небес, питая Озарение и Прилив Света."
L["Light's Vigil turns Holy Shock into a group-heal burst; this is the signature Forever Holy talent."] = "Бдение Света превращает Шок небес во всплеск группового исцеления; это фирменный талант Света на Forever."
L["The remaining 20 points go to Retribution: cheaper spells and more melee crit while questing, ending in Seal of Command."] = "Оставшиеся 20 очков идут в Воздаяние: более дешевые заклинания и больше критических ударов в ближнем бою при выполнении заданий, а в конце — Печать повеления."
L["Open with Redoubt: blocking pays off at once, and Shield Specialization needs all five ranks."] = "Начните с Несокрушимости: блок окупается сразу, а Специализации на щитах нужны все пять рангов."
L["Precision and Anticipation help you land hits and dodge them while questing with a shield."] = "Точность и Предвидение помогают попадать и уклоняться при выполнении заданий со щитом."
L["Improved Seal of Fury and Improved Righteous Fury begin the mana and mitigation cycle Forever tanking is built on."] = "Улучшенная печать ярости и Улучшенное праведное неистовство запускают цикл маны и снижения урона, на котором построено танкование на Forever."
L["Around 20 points in, you match the usual dungeon-tank setup: Shield Specialization, Sacred Duty and Swift Judgement are complete."] = "Примерно к 20 очкам вы получаете обычную сборку танка подземелий: Специализация на щитах, Священный долг и Быстрое правосудие завершены."
L["Templar's Bulwark is an absorb cooldown that scales with your health, and Holy Shield later in the plan requires it."] = "Оплот тамплиера — поглощающая способность с перезарядкой, зависящая от вашего здоровья; она требуется для Щита небес позже в плане."
L["Iron Creed adds threat and damage reduction to Holy Strike while Righteous Fury is active."] = "Железное кредо добавляет угрозу и снижение урона к Удару Света, пока активно Праведное неистовство."
L["Holy Shield is the capstone: more block uptime, with Holy damage each time you block. Ideal for pulling packs."] = "Щит небес — вершина ветки: блок чаще, и каждый блок наносит урон от сил Света. Идеально для пулла групп противников."
L["Leftover points buy armor, a quicker Hammer of Justice, and Holy Strength and seal damage for leveling."] = "Оставшиеся очки идут на броню, более быстрый Молот правосудия, а также Силу небес и урон печатей для прокачки."
L["Benediction lowers the mana cost of Judgement, Holy Strike and seals, so you rest less between fights."] = "Благодать снижает стоимость Правосудия, Удара Света и печатей, так что между боями отдыхать нужно меньше."
L["Seal of Command is the main two-hander seal for leveling; take it as soon as it opens."] = "Печать повеления — основная печать для двуручного оружия при прокачке; берите ее, как только она откроется."
L["Sanctified Judgement gives mana back and is the prerequisite arrow for Vengeance."] = "Освященное правосудие возвращает ману и является обязательной стрелкой к Отмщению."
L["Sacred Arbiter strengthens Holy Strike and keeps Judgements rolling, and completes the 20 points row 5 asks for."] = "Священный арбитр усиливает Удар Света, поддерживает Правосудие и добирает 20 очков, нужных для 5-го ряда."
L["Vengeance, then Two-Handed Weapon Specialization: the crit-driven damage core of the two-hander plan."] = "Отмщение, затем Специализация на двуручном оружии: критическое ядро урона плана с двуручным оружием."
L["Pursuit of Justice adds run speed. Champion of the Light is left out while the Retribution Aura spell-power bug keeps spell damage low."] = "Поиск справедливости повышает скорость бега. Поборник Света не берется, пока ошибка силы заклинаний Ауры воздаяния занижает урон от заклинаний."
L["Twist of Light makes swapping seals cheaper and adds seal echoes; it is Forever's seal-twisting talent."] = "Поворот Света удешевляет смену печатей и добавляет эхо печатей; это талант Forever для переключения печатей."
L["Spare points go to Divine Strength and Holy's Improved Seals for damage, then Deflection for survival."] = "Свободные очки идут в Божественную силу и Улучшенные печати Света ради урона, затем в Отражение ради выживаемости."
L["Level as Combat with a sword (Riposte, Blade Flurry, Adrenaline Rush) for the steadiest kills, or Assassination with daggers and poisons (Mutilate). Subtlety's Hemorrhage plan suits stealth openers and is slower solo."] = "Качайтесь в Бою с мечом (Ответный удар, Шквал клинков, Прилив адреналина) для стабильных убийств или в Ликвидации с кинжалами и ядами (Добить). Хеморрагия в Скрытности подходит для открытия из-за скрытности, но в одиночку медленнее."
L["Malice first: crit for every attack and poison, and it opens Lethality."] = "Сначала Злоба: шанс критического удара для каждой атаки и яда, и открывает Смертоносность."
L["Ruthlessness gives finishers a chance at a free combo point; Murder adds damage against humanoids and giants."] = "Беспощадность даёт финальным ударам шанс получить бесплатное очко комбо; Убийство добавляет урон по гуманоидам и великанам."
L["Relentless Strikes refunds energy from finishers, so fights flow without waiting."] = "Неослабевающие удары возвращают энергию от финальных ударов, так что бой идёт без пауз."
L["Improved Poisons puts poisons on more often and makes charges last; take them as soon as you train poisons."] = "Улучшенные яды наносят яд чаще и продлевают заряды; берите, как только изучите яды."
L["Mutilate is Forever's dual-wield dagger strike: two combo points a use, and more damage on poisoned targets."] = "Добить — удар кинжалом в двух руках в Forever: два очка комбо за применение и больше урона по отравленным целям."
L["Seal Fate turns crits into extra combo points; with Malice and Lethality it is the core of the build."] = "Печать судьбы превращает критические удары в дополнительные очки комбо; вместе со Злобой и Смертоносностью это ядро сборки."
L["Venom is the capstone: a finisher that strengthens your poisons for a while."] = "Яд — вершина ветки: финальный удар, усиливающий ваши яды на некоторое время."
L["The last 20 points go to Combat: cheaper Sinister Strikes, a stronger Eviscerate, more hit and parry, Riposte and a stronger off-hand."] = "Последние 20 очков идут в Бой: более дешёвые Коварные удары, более мощное Потрошение, больше меткости и парирования, Ответный удар и более сильная вспомогательная рука."
L["Improved Sinister Strike first: cheaper Sinister Strikes are the biggest early gain."] = "Сначала Улучшенный коварный удар: более дешёвые Коварные удары — самая большая ранняя выгода."
L["Precision helps you hit more often; it also opens Dual Wield Specialization."] = "Точность помогает чаще попадать; также открывает Специализацию на двух оружиях."
L["Riposte follows each parry with a heavy strike that also disarms."] = "Ответный удар после каждого парирования наносит мощный удар, также обезоруживающий цель."
L["Blade Flurry is faster attacks and cleave on demand; Hack and Slash then adds extra attacks with swords and axes."] = "Шквал клинков — ускоренные атаки и рассекание по требованию; Рубить и резать добавляет дополнительные атаки с мечами и топорами."
L["Adrenaline Rush is the capstone: double energy for 15 seconds, enough for a second mob."] = "Прилив адреналина — вершина ветки: двойная энергия на 15 секунд, достаточно для второго противника."
L["The remaining points go to Assassination for crit, free combo points, energy refunds and Lethality."] = "Оставшиеся очки идут в Ликвидацию ради критических ударов, бесплатных очков комбо, возврата энергии и Смертоносности."
L["Opportunity adds damage to Backstab, Ambush and Garrote, your stealth openers."] = "Возможность добавляет урон к Удару в спину, Засаде и Удавке — вашим умениям открытия из скрытности."
L["Improved Ambush and Initiative make the opener the fight: a likely crit and extra combo points."] = "Улучшенная засада и Инициатива делают открытие боя его ядром: вероятный критический удар и дополнительные очки комбо."
L["Serrated Blades ignores armor and is the way into Hemorrhage."] = "Зазубренные лезвия игнорируют броню и являются путём к Кровотечению."
L["Hemorrhage is your main builder from here, with any weapon, and it adds to Rupture damage."] = "Кровотечение — ваш основной генератор очков комбо отныне, с любым оружием, и добавляет к урону Разрыва."
L["Quietus adds damage to Hemorrhage and Ghostly Strike on a low-health target, finishing mobs sooner."] = "Безмолвие добавляет урон к Кровотечению и Призрачному удару по цели с малым запасом здоровья, ускоряя уничтожение противников."
L["Thousand Cuts is the capstone: Rupture ticks make your next Hemorrhage cheaper."] = "Тысяча порезов — вершина ветки: тики Разрыва делают следующее Кровотечение дешевле."
L["Level as Arms with a two-hander (Mortal Strike, Sweeping Strikes) or Fury (Enrage, Death Wish, then Flurry and Bloodthirst with two weapons). Protection is slower alone but ready to tank any dungeon on the way."] = "Качайтесь в Оружии с двуручным оружием (Смертельный удар, Широкий взмах) или в Неистовстве (Ярость, Желание смерти, затем Вихрь и Жажда крови с двумя оружиями). Защита медленнее в одиночку, но готова танковать любое подземелье по пути."
L["Improved Heroic Strike first: Heroic Strike is your main rage dump, and a cheaper one means more of them."] = "Сначала Улучшенный героический удар: Героический удар — ваш основной расходник ярости, и более дешёвый означает большее их количество."
L["Improved Tactical Mastery keeps rage when you swap stances, so Charge, Overpower and Battle Stance openers cost you nothing."] = "Улучшенное тактическое мастерство сохраняет ярость при смене стойки, поэтому Натиск, Контратака и открытие в Боевой стойке не стоят ничего."
L["Anger Management is a steady rage trickle in every fight; on Forever it also slows rage loss between pulls."] = "Управление гневом даёт стабильный приток ярости в каждом бою; в Forever также замедляет потерю ярости между схватками."
L["Improved Rend and Deep Wounds turn your crits into bleeds; Deep Wounds also opens Impale."] = "Улучшенное Разрывание и Глубокие раны превращают критические удары в кровотечения; Глубокие раны также открывают Пронзание."
L["Sweeping Strikes makes two-mob pulls quick; Weaponmaster then adds crit, armor penetration or extra attacks for your weapon type."] = "Широкий взмах делает пулл двух противников быстрым; Мастер оружия добавляет шанс крита, пробивание брони или дополнительные атаки для вашего типа оружия."
L["Improved Slam stops Slam from resetting your swing: a free hit between big two-hander swings."] = "Улучшенный Удар не сбрасывает вашу атаку: бесплатный удар между взмахами двуручного оружия."
L["Mortal Strike is the capstone and your hardest-hitting strike for the rest of the climb."] = "Смертельный удар — вершина ветки и ваш самый мощный удар до конца прокачки."
L["The last 20 points go to Fury: Cruelty and Unbridled Wrath give more crit and more rage."] = "Последние 20 очков идут в Неистовство: Жестокость и Необузданный гнев дают больше крита и ярости."
L["Enrage finishes the plan: a damage boost that is often up while you take hits."] = "Ярость завершает план: прирост урона, который часто активен, пока вы получаете удары."
L["Cruelty first: more crit for every build, and the way into the Fury tree."] = "Сначала Жестокость: больше крита для любой сборки и путь в дерево Неистовства."
L["Unbridled Wrath means more rage from every swing, which matters most with two fast weapons."] = "Необузданный гнев даёт больше ярости от каждого взмаха, что наиболее важно с двумя быстрыми оружиями."
L["Piercing Howl stops runners and lets you walk away from a bad pull."] = "Пронизывающий вой останавливает убегающих и позволяет выйти из неудачного пулла."
L["Enrage raises your physical damage after you are hit, so it is often up while you take hits."] = "Ярость повышает физический урон после получения удара, поэтому часто активна во время получения ударов."
L["Death Wish is a big cooldown for elites and a fear breaker; it also opens Flurry."] = "Желание смерти — мощная способность с перезарядкой против элит и снятие страха; также открывает Вихрь."
L["Dual Wield Specialization: more off-hand damage and rage now that you carry two weapons."] = "Специализация на двух оружиях: больше урона от вспомогательной руки и ярости теперь, когда у вас два оружия."
L["Bloodthirst is the capstone: a strong instant attack and a little run speed between mobs."] = "Жажда крови — вершина ветки: мощная мгновенная атака и небольшое ускорение передвижения между противниками."
L["Gore Drinker turns your rage cooldowns into self-healing, so you rest less."] = "Пьющий кровь превращает ваши кулдауны ярости в самолечение, так что вы меньше отдыхаете."
L["Spare points go to Arms for cheaper Heroic Strikes, stance-swap rage, Anger Management and Deep Wounds."] = "Свободные очки идут в Оружие ради более дешёвых Героических ударов, ярости при смене стойки, Управления гневом и Глубоких ран."
L["Shield Specialization: more blocks, and on Forever each block also gives rage."] = "Специализация на щитах: больше блоков, и в Forever каждый блок также даёт ярость."
L["Improved Revenge makes Revenge, which you can use after each block, a real damage hit."] = "Улучшенный Удар возмездия превращает Удар возмездия, который можно использовать после каждого блока, в полноценный удар с уроном."
L["Last Stand is your emergency cooldown when a pull goes wrong."] = "Последний рубеж — ваш экстренный кулдаун, когда пулл идёт не так."
L["Vanguard lets you Charge from Defensive Stance: no stance dance to open a pull."] = "Авангард позволяет делать Натиск из Оборонительной стойки: не нужно переключать стойки для начала пулла."
L["Concussion Blow is a stun on demand, for an interrupt or to reach a runner."] = "Сотрясающий удар — оглушение по требованию, для прерывания или чтобы догнать убегающего."
L["Bastion adds damage to everything you do with a shield on; it is what makes Protection level well."] = "Бастион добавляет урон ко всему, что вы делаете со щитом; именно это делает Защиту эффективной при прокачке."
L["Shield Slam is the capstone: a big hit that grows with your block value, and high threat for dungeons."] = "Удар щитом — вершина ветки: мощный удар, растущий вместе с вашей защитой блока, и высокая угроза для подземелий."
L["Defiance, Improved Thunder Clap and Improved Shield Wall round out the tank kit for dungeons."] = "Смелость, Улучшенный Удар грома и Улучшенная Стена щитов завершают танковый арсенал для подземелий."
L["The last 10 points go to Arms: cheaper Heroic Strikes and Improved Tactical Mastery for swaps to Battle Stance."] = "Последние 10 очков идут в Оружие: более дешёвые Героические удары и Улучшенное тактическое мастерство для переходов в Боевую стойку."
L["Level as Frost (the safest: slows, freezes and Ice Barrier) or Fire (more damage, with Pyroblast openers and Blast Wave). Arcane builds around Arcane Blast and Arcane Power and wants more mana between pulls."] = "Качайтесь в Льде (самый безопасный: замедления, заморозки и Ледяной барьер) или в Огне (больше урона, с открытием Огненного шара и Взрывной волной). Тайная сила строится вокруг Тайного взрыва и Тайной мощи и требует больше маны между схватками."
L["Improved Channeling first: Arcane Missiles, and later Arcane Blast, keep going when a mob hits you."] = "Сначала Улучшенная концентрация: Тайные снаряды и позже Тайный взрыв продолжают работать, когда вас атакует противник."
L["Arcane Concentration gives free casts now and then, and opens Arcane Meditation."] = "Тайная концентрация иногда даёт бесплатные заклинания и открывает Тайную медитацию."
L["Arcane Blast is Forever's Arcane builder: each cast adds spell power for the next."] = "Тайный взрыв — генератор Тайных сил в Forever: каждое применение добавляет мощь заклинаний для следующего."
L["Missile Barrage: Arcane Blast, Arcane Wrath, Fireball and Frostbolt can make your next Arcane Missiles faster and cheaper."] = "Обстрел снарядами: Тайный взрыв, Тайный гнев, Огненный шар и Ледяная стрела могут сделать следующие Тайные снаряды быстрее и дешевле."
L["Arcane Meditation keeps mana coming back while you cast, so you drink less."] = "Тайная медитация восстанавливает ману во время заклинаний, поэтому вы меньше пьёте."
L["Arcane Wrath, opened by Arcane Blast, is a nuke that grows with your maximum mana. Its point does not count toward the Arcane tiers, so the plan spends 32 points in Arcane."] = "Тайный гнев, открываемый Тайным взрывом, — это нюк, растущий с вашим максимумом маны. Его очко не засчитывается в тиры Тайных сил, поэтому план тратит 32 очка в Тайных силах."
L["Presence of Mind makes one spell instant: an opener, or a finisher on a runner."] = "Присутствие духа делает одно заклинание мгновенным: открытие боя или финальный удар по убегающему."
L["Arcane Power is the capstone: more damage for more mana, best with Presence of Mind on a tough target."] = "Тайная мощь — вершина ветки: больше урона за больше маны, лучше всего с Присутствием духа против сложной цели."
L["The remaining 19 points go to Frost for a quicker Frostbolt, a shorter Frost Nova cooldown, longer slows and Ice Block."] = "Оставшиеся 19 очков идут во Лёд: более быстрая Ледяная стрела, более короткое время перезарядки Ледяного покрова, более длинные замедления и Ледяной блок."
L["Improved Fireball first: a faster Fireball is more damage every fight."] = "Сначала Улучшенный Огненный шар: более быстрый Огненный шар — это больше урона в каждом бою."
L["Ignite adds burn damage to every Fire crit."] = "Воспламенение добавляет урон от ожога к каждому критическому удару Огнём."
L["Pyroblast is a big opener from range; cast it first, then Fireball."] = "Огненный шар — мощное открытие с расстояния; используйте его первым, затем Огненный шар."
L["Master of Elements gives mana back on crits, so you rest less."] = "Мастер стихий возвращает ману при критических ударах, так что вы меньше отдыхаете."
L["Critical Mass and Blast Wave: more crits, and an area attack and daze for when two mobs reach you."] = "Критическая масса и Взрывная волна: больше крита и атака по площади с оглушением, когда два противника добираются до вас."
L["Fire Power raises your Fire damage for each of your Fire effects on the target: Ignite, Pyroblast's burn and the like."] = "Мощь огня повышает урон Огнём за каждый эффект Огня на цели: Воспламенение, ожог от Огненного шара и подобное."
L["Combustion is the capstone: a crit cooldown for elites and big pulls."] = "Сгорание — вершина ветки: кулдаун критического удара для элит и больших пуллов."
L["The last 20 points go to Arcane: a stronger wand for finishing mobs, then Arcane Concentration's free casts and Arcane Meditation's regen while casting."] = "Последние 20 очков идут в Тайные силы: более мощная палочка для добивания, затем бесплатные заклинания Тайной концентрации и восстановление маны при заклинаниях Тайной медитации."
L["Improved Frostbolt first: a faster Frostbolt is your main gain for the early levels."] = "Сначала Улучшенная Ледяная стрела: более быстрая Ледяная стрела — ваш главный выигрыш на ранних уровнях."
L["Ice Shards makes Frost crits hit much harder."] = "Ледяные осколки делают критические удары Льдом значительно сильнее."
L["Improved Frost Nova and Ice Block are your escapes: freeze, step back, keep casting."] = "Улучшенный Ледяной покров и Ледяной блок — ваш побег: заморозить, отступить, продолжать заклинания."
L["Shatter adds a large crit chance against frozen targets: Frost Nova, then Frostbolt or Ice Lance."] = "Дробление добавляет высокий шанс крита против замороженных целей: Ледяной покров, затем Ледяная стрела или Ледяное копьё."
L["Ice Barrier is the capstone: an absorb shield that also stops pushback while you cast."] = "Ледяной барьер — вершина ветки: щит поглощения, который также останавливает прерывание заклинаний при ударах."
L["Level as Affliction (instant Corruption, Siphon Life, drains) or Demonology (a tougher Voidwalker, Soul Link) for the fewest deaths. Destruction hits hardest with Conflagrate and Incinerate but needs more rest."] = "Качайтесь в Колдовстве (мгновенная Порча, Всасывание жизни, истощения) или Демонологии (более крепкий Пустотный страж, Связь душ) для наименьшего числа смертей. Разрушение бьёт сильнее всего с Возгоранием и Испепелением, но требует больше отдыха."
L["Improved Corruption makes Corruption instant: the core of Affliction leveling."] = "Улучшенная Порча делает Порчу мгновенной: основа прокачки Колдовства."
L["Improved Drains and Soul Harvest make Drain Life a heal and Drain Soul a mana return on kills."] = "Улучшенные истощения и Сбор душ делают Высасывание жизни исцелением, а Высасывание души — возвратом маны при убийствах."
L["Nightfall gives an instant Shadow Bolt now and then while your damage over time ticks."] = "Ночное падение иногда даёт мгновенный Тёмный снаряд, пока тикают ваши эффекты периодического урона."
L["Siphon Life adds another self-heal over time to the rotation."] = "Всасывание жизни добавляет ещё одно самоисцеление с течением времени в ротацию."
L["Shadow Mastery adds damage to every Shadow spell."] = "Мастерство теней добавляет урон каждому заклинанию Тьмы."
L["Wrack is the capstone: a strong channel that raises the damage the target takes from your other Shadow damage-over-time effects by 10%."] = "Терзание — завершающий талант ветки: мощное поддерживаемое заклинание, которое на 10% увеличивает урон, получаемый целью от других ваших эффектов периодического урона от темной магии."
L["The last 20 points go to Demonology: more Stamina, a tougher Voidwalker, quicker summons and Demonic Sacrifice."] = "Последние 20 очков идут в Демонологию: больше Выносливости, более крепкий Пустотный страж, более быстрые призывы и Демоническое жертвоприношение."
L["Demonic Embrace first: more Stamina means more Life Taps and fewer deaths."] = "Сначала Демонические объятия: больше Выносливости означает больше Высасываний жизни и меньше смертей."
L["Improved Voidwalker makes your tank pet hold mobs better and shield you."] = "Улучшенный Пустотный страж заставляет вашего питомца-танка лучше удерживать противников и защищать вас."
L["Soul Link shares your damage with your pet: with a Voidwalker you rarely die."] = "Связь душ делит ваш урон с питомцем: с Пустотным стражем вы редко умираете."
L["Demonic Pact is the capstone: you keep Demonic Sacrifice's effect when you summon another demon."] = "Демонический пакт — вершина ветки: вы сохраняете эффект Демонического жертвоприношения при призыве другого демона."
L["The rest goes to Affliction: an instant Corruption, stronger drains and Life Tap, and Nightfall's free Shadow Bolts."] = "Остальное идёт в Колдовство: мгновенная Порча, более сильные истощения и Высасывание жизни, и бесплатные Тёмные снаряды от Ночного падения."
L["Bane first: faster Shadow Bolts and Immolates."] = "Сначала Проклятие: более быстрые Тёмные снаряды и Испепеления."
L["Ruin makes Destruction crits hit much harder."] = "Погибель делает критические удары Разрушения значительно сильнее."
L["Conflagrate turns your Immolate into burst damage; open with Immolate, then Conflagrate."] = "Возгорание превращает ваше Испепеление в взрывной урон; открывайте Испепелением, затем Возгоранием."
L["Incinerate is the capstone: a strong Fire nuke, best on an Immolated target."] = "Испепеление — вершина ветки: мощный нюк Огнём, лучший против цели, на которую наложено Жертвоприношение."
L["Level as Feral Combat: Cat Form for quick kills, Bear Form for tough pulls, and no drinking. Balance kills from range with roots and Starfire; Restoration heals any dungeon and quests slowly with Wrath."] = "Качайтесь в Дикости: Форма кошки для быстрых убийств, Форма медведя для сложных пуллов, без необходимости пить. Равновесие убивает на расстоянии с помощью корней и Звёздного огня; Исцеление лечит любое подземелье и медленно выполняет задания с Гневом."
L["Improved Wrath first: a faster, cheaper Wrath is most of your early damage."] = "Сначала Улучшенный Гнев: более быстрый и дешёвый Гнев — это большая часть вашего раннего урона."
L["Moonglow and Nature's Majesty: cheaper spells and more crit."] = "Лунное сияние и Величие природы: более дешёвые заклинания и больше крита."
L["Improved Entangling Roots holds a mob in place while you nuke it from range."] = "Улучшенные Цепляющие корни удерживают противника на месте, пока вы атакуете его с расстояния."
L["Nature's Grace speeds up your next spell after a crit."] = "Дар природы ускоряет ваше следующее заклинание после крита."
L["Moonkin Form is the capstone: armor and more free casts while you nuke."] = "Лунная форма — вершина ветки: броня и больше бесплатных заклинаний во время атаки."
L["The last 20 points go to Restoration: fewer interrupted casts, Naturalist's damage, regen while casting and stronger heals."] = "Последние 20 очков идут в Исцеление: меньше прерваний заклинаний, урон Натуралиста, восстановление при заклинаниях и более сильное исцеление."
L["Ferocity first: cheaper Claw, Rake and Maul in both forms."] = "Сначала Свирепость: более дешёвые Коготь, Царапина и Дубась в обеих формах."
L["Savage Fury and Sharpened Claws add damage and crit in Cat and Bear Form."] = "Свирепая ярость и Заострённые когти добавляют урон и крит в формах Кошки и Медведя."
L["Predatory Strikes adds attack power in forms; it scales with your level, not your gear."] = "Хищные удары добавляют силу атаки в формах; масштабируется с вашим уровнем, а не снаряжением."
L["Leader of the Pack adds crit for you and your group."] = "Вожак стаи добавляет шанс крита для вас и вашей группы."
L["Berserk is the capstone: a cooldown that makes Primal Bite hit several targets."] = "Берсерк — вершина ветки: кулдаун, который заставляет Изначальный укус поражать несколько целей."
L["The last 20 points go to Restoration: rage when you shift, Naturalist's damage, cheaper shifting and regen while casting."] = "Последние 20 очков идут в Исцеление: ярость при смене формы, урон Натуралиста, более дешёвая смена формы и восстановление при заклинаниях."
L["Nature's Focus first: your casts go through while a mob hits you."] = "Сначала Концентрация природы: ваши заклинания проходят, пока противник вас атакует."
L["Reflection keeps mana coming back while casting, so you rest less."] = "Отражение восстанавливает ману во время заклинаний, так что вы меньше отдыхаете."
L["Swiftmend uses up a Rejuvenation or Regrowth for a big instant heal."] = "Стремительное исцеление расходует Омоложение или Возрождение для мощного мгновенного исцеления."
L["Wild Growth is the capstone: a heal over time on your whole group."] = "Дикий рост — вершина ветки: периодическое исцеление для всей вашей группы."
L["The last 20 points go to Balance so you can still kill quest mobs: a faster, cheaper Wrath, roots and more crit."] = "Последние 20 очков идут в Равновесие, чтобы вы всё ещё могли убивать квестовых противников: более быстрый и дешёвый Гнев, корни и больше крита."
L["Level as Enhancement (Flurry, Stormstrike, Maelstrom Weapon) for steady melee with few rests, or Elemental (Lightning Overload, Lava Burst) to kill from range. Restoration heals dungeons well and levels slowly alone."] = "Качайтесь в Совершенствовании (Вихрь, Удар ветра, Оружие Водоворота) для стабильного ближнего боя с редкими остановками, или в Стихиях (Перегрузка стихий, Взрыв лавы) для дальних убийств. Исцеление хорошо лечит подземелья, но медленно качается в одиночку."
L["Concussion first: more damage from Lightning Bolt and Earth Shock, your two main spells."] = "Сначала Сотрясение: больше урона от Молнии и Удара земли — ваших двух основных заклинаний."
L["Elemental Focus makes some casts free, which is the main mana saver for the early levels."] = "Концентрация стихий делает некоторые заклинания бесплатными — это главный экономитель маны на ранних уровнях."
L["Lava Burst is a big Fire nuke, best after Flame Shock; Call of Flame makes it stronger."] = "Взрыв лавы — мощный нюк Огнём, лучший после Удара пламени; Зов пламени делает его сильнее."
L["Lightning Overload sometimes casts a second, smaller Lightning Bolt for free."] = "Перегрузка стихий иногда бесплатно выпускает второй, меньший Удар молнии."
L["Elemental Mastery is the capstone: for a while, quicker Lightning Bolts and Lava Bursts and no cooldown on Chain Lightning."] = "Мастерство стихий — вершина ветки: на некоторое время более быстрые Молнии и Взрывы лавы и никакого кулдауна на Цепную молнию."
L["The last 20 points go to Enhancement: more Intellect, more crit, a stronger Lightning Shield and cheaper Shocks."] = "Последние 20 очков идут в Совершенствование: больше Интеллекта, больше крита, более мощный Молниевый щит и более дешёвые Удары."
L["Thundering Strikes first: crit for spells and attacks, and the way into the tree."] = "Сначала Громовые удары: крит для заклинаний и атак и путь в дерево."
L["Mental Dexterity turns your Intellect into attack power, so mana gear helps your melee too; it also opens Flurry."] = "Умственная ловкость превращает Интеллект в силу атаки, поэтому предметы с маной помогают и ближнему бою; также открывает Вихрь."
L["Flurry speeds up your swings after a crit and is the core of Enhancement's damage."] = "Вихрь ускоряет ваши удары после критического удара и является основой урона Совершенствования."
L["Stormstrike is an instant strike that raises the damage your next spells do."] = "Удар ветра — мгновенный удар, повышающий урон ваших следующих заклинаний."
L["Maelstrom Weapon makes your next Lightning Bolt faster and cheaper as you hit."] = "Оружие Водоворота делает следующую Молнию быстрее и дешевле по мере нанесения ударов."
L["Rage of the Farseer is the capstone: a big attack-speed cooldown for elites and pulls."] = "Ярость провидца — вершина ветки: мощный кулдаун скорости атаки для элит и пуллов."
L["The last 20 points go to Elemental for stronger Shocks, cheaper casts and more crit from spells."] = "Последние 20 очков идут в Стихии: более мощные Удары, более дешёвые заклинания и больше крита от заклинаний."
L["Tidal Focus first: cheaper heals, and more hit for your Lightning Bolts while you quest."] = "Сначала Приливная концентрация: более дешёвое исцеление и больше меткости для Молний во время квестов."
L["Totemic Focus: cheaper totems, which you drop on every pull while leveling."] = "Тотемная концентрация: более дешёвые тотемы, которые вы ставите при каждом пулле во время прокачки."
L["Mindfulness keeps half your mana regeneration going while casting."] = "Внимательность поддерживает половину восстановления маны во время заклинаний."
L["Nature's Swiftness makes one heal instant: your emergency button."] = "Быстрота природы делает одно исцеление мгновенным: ваша аварийная кнопка."
L["Riptide is the capstone: a quick heal with a heal over time for dungeons."] = "Прибой — вершина ветки: быстрое исцеление с периодическим эффектом для подземелий."
L["The last 20 points go to Elemental, so your Lightning Bolts and Shocks still kill while you quest."] = "Последние 20 очков идут в Стихии, чтобы ваши Молнии и Удары всё ещё убивали во время квестов."
L["Feral Combat"] = "Дикость"
L["Restoration"] = "Исцеление"
L["Level as Beast Mastery: your pet tanks and does much of the damage, so you rarely stop. Marksmanship hits harder from range with Careful Aim and Sniper Shot; Survival fights in melee with Predator's Edge and Lacerating Strikes."] = "Качайтесь в Укрощении зверя: ваш питомец танкует и наносит большую часть урона, поэтому вы редко останавливаетесь. Меткость бьёт сильнее с дальней дистанции с Тщательным прицелом и Выстрелом снайпера; Выживание сражается в ближнем бою с Преимуществом хищника и Рвущими ударами."
L["Deadly Aspects first: more from Aspect of the Hawk while your pet holds the mob."] = "Сначала Смертоносные аспекты: больше от Аспекта Ястреба, пока ваш питомец удерживает противника."
L["Unleashed Fury adds pet damage, and your pet is most of your damage."] = "Высвобожденная ярость добавляет урон питомца, а питомец — основная часть вашего урона."
L["Intimidation stuns through your pet: a breather when a mob turns on you."] = "Запугивание оглушает через вашего питомца: передышка, когда противник нападает на вас."
L["Bestial Wrath is the capstone: your pet's big damage cooldown."] = "Звериная ярость — вершина ветки: мощный кулдаун урона вашего питомца."
L["The last 20 points go to Marksmanship: more crit, attack power from Intellect, a shorter Rapid Fire and harder ranged crits."] = "Последние 20 очков идут в Меткость: больше крита, сила атаки от Интеллекта, более короткий Шквальный огонь и более сильные критические удары с расстояния."
L["Lethal Attacks first: crit for every shot."] = "Сначала Смертоносные атаки: крит для каждого выстрела."
L["Careful Aim adds attack power from your Intellect."] = "Тщательный прицел добавляет силу атаки от вашего Интеллекта."
L["Mortal Shots makes your ranged crits hit much harder."] = "Смертоносные выстрелы делают критические удары с расстояния значительно сильнее."
L["Sniper Shot is the capstone: a long-range opener that hits hard."] = "Выстрел снайпера — вершина ветки: дальнобойное открытие боя, бьющее сильно."
L["The last 20 points go to Beast Mastery: a stronger Aspect of the Hawk and a tougher, harder-hitting pet."] = "Последние 20 очков идут в Укрощение зверя: более мощный Аспект Ястреба и более крепкий, наносящий больше урона питомец."
L["Improved Tracking first: keep tracking on for its bonus against the mobs you quest on."] = "Сначала Улучшенное слежение: держите слежение включённым ради его бонуса против квестовых противников."
L["Deterrence is a dodge and parry cooldown for melee fights that go wrong."] = "Сдерживание — кулдаун уклонения и парирования для рукопашных схваток, которые идут не так."
L["Lightning Reflexes adds Agility: more attack power, crit and dodge."] = "Молниеносные рефлексы добавляют Ловкость: больше силы атаки, крита и уклонения."
L["Lacerating Strikes is the capstone: Mongoose Bite also makes the target bleed."] = "Рвущие удары — вершина ветки: Укус мангуста также заставляет цель истекать кровью."
L["Level as Shadow (Spirit Tap, Mind Flay, Shadowform) for the fastest kills and least drinking. Discipline levels with Smite and Penance behind a strong shield; Holy is the dungeon healer and slower alone."] = "Качайтесь в Тьме (Духовный отвод, Ментальный разрыв, Форма тени) для быстрейших убийств и меньшего количества питья. Послушание качается с Наказанием и Покаянием за мощным щитом; Свет — целитель подземелий и медленнее в одиночку."
L["Power in Light first: more Smite damage, your main attack as Discipline, on targets with your Holy Fire or Shadow Word: Pain."] = "Сначала Сила в Свете: больше урона Наказания — вашей основной атаки в Послушании — против целей с Огнём Света или Словом тьмы: Боль."
L["Improved Power Word: Shield: a bigger shield is fewer interrupted casts and less healing."] = "Улучшенное Слово силы: Щит: более мощный щит означает меньше прерываний заклинаний и меньше исцеления."
L["Penance is a channelled burst of Holy damage or healing: use it on every mob."] = "Покаяние — это концентрированный поток урона или исцеления Светом: используйте против каждого противника."
L["Power Infusion is the capstone: a damage and healing cooldown for you or an ally."] = "Вливание силы — вершина ветки: кулдаун урона и исцеления для вас или союзника."
L["The last 20 points go to Shadow: Spirit Tap's regen after kills, a longer Shadow Word: Pain, more Shadow hit, Mind Flay and a quicker Mind Blast."] = "Последние 20 очков идут в Тьму: восстановление от Духовного отвода после убийств, более длинное Слово тьмы: Боль, больше меткости Тьмы, Ментальный разрыв и более быстрый Ментальный взрыв."
L["Holy Specialization first: more crits on Smite and on your heals."] = "Сначала Специализация Света: больше крита в Наказании и ваших исцелениях."
L["Divine Fury speeds up Smite, Holy Fire and your big heals."] = "Божественный гнев ускоряет Наказание, Священный огонь и ваши мощные исцеления."
L["Spiritual Guidance adds 25% of your Spirit to your healing but only 8% to your damage: Spirit gear helps your heals most."] = "Духовное наставление добавляет 25% духа к исцелению, но лишь 8% к урону: экипировка с духом больше всего помогает исцелению."
L["Prayer of Mending is the capstone: a heal that jumps between your group as they take damage."] = "Молитва об исцелении — вершина ветки: исцеление, перепрыгивающее между членами вашей группы при получении урона."
L["The last 20 points go to Discipline: a stronger wand, a bigger Power Word: Shield, Meditation's regen while casting and more Intellect."] = "Последние 20 очков идут в Послушание: более мощная палочка, более мощное Слово силы: Щит, восстановление Медитации при заклинаниях и больше Интеллекта."
L["Mental Strength comes last: on Forever its points do not count toward the Discipline tiers."] = "Сила разума идёт последней: в Forever её очки не засчитываются в тиры Послушания."
L["Spirit Tap first: after each kill your regen jumps, so you drink far less."] = "Сначала Духовный отвод: после каждого убийства восстановление резко возрастает, так что вы пьёте значительно меньше."
L["Mind Flay is your main damage and slow from here; Improved Mind Flay makes it hit harder."] = "Ментальный разрыв — ваш основной урон и замедление отныне; Улучшенный ментальный разрыв делает его сильнее."
L["Vampiric Embrace heals you from your Shadow damage."] = "Вампирские объятия исцеляют вас от вашего урона Тьмой."
L["Shadowform is the capstone: more Shadow damage and less physical damage taken."] = "Форма тени — вершина ветки: больше урона Тьмой и меньше полученного физического урона."
L["ForeverDB through level 30, Polestar after"] = "ForeverDB до 30-го уровня, далее Polestar"
L["Polestar, with ForeverDB's builds to level 20"] = "Polestar, с планами ForeverDB до 20-го уровня"
L["Polestar, with ForeverDB's talent data"] = "Polestar, с данными о талантах ForeverDB"
L["ForeverDB"] = "ForeverDB"
L["ForeverDB's leveling builds, adapted to level 30"] = "Планы прокачки ForeverDB, адаптированные до 30-го уровня"

-- Nav/Handoff.lua
L["Hand guiding to Shortest Path Forever"] = "Передать ведение Shortest Path Forever"
L["Shortest Path Forever's arrow, route and journey take you to each goal. Polestar's arrow, route lines, journey steps, travel button, transport alerts, map clicks and /way step aside; the guide window and map pins stay. Off: Polestar guides, and steps aside only while a journey you started in Shortest Path Forever runs."] = "Стрелка, маршрут и путь Shortest Path Forever ведут к каждой цели. Стрелка Polestar, линии маршрута, шаги пути, кнопка пути, оповещения о транспорте, щелчки по карте и /way отключаются; окно гайда и метки на карте остаются. Выкл.: ведет Polestar и уступает только на время пути, начатого в Shortest Path Forever."

-- Core/Import.lua
L["Imported"] = "Импортированные"
L["This import string is damaged or incomplete. Copy the whole string again."] = "Строка импорта повреждена или неполна. Скопируйте ее целиком еще раз."
L["This import string needs a newer Polestar."] = "Для этой строки импорта нужна более новая версия Polestar."
L["This import string holds no guide."] = "В этой строке импорта нет гайда."
L["Its guide id %s must start with its author's own id, as in yendi/cozy-sleeping-bag."] = "Идентификатор гайда %s должен начинаться с собственного идентификатора автора, как в yendi/cozy-sleeping-bag."
L["Guides under %s/ come from the community addon %s, which is installed."] = "Гайды с префиксом %s/ поставляет аддон сообщества %s, и он установлен."
L["Its guide has %d steps; an import string holds %d at most. A bigger guide comes as a community addon."] = "В гайде %d шагов, а строка импорта вмещает не больше %d. Гайд побольше распространяется как аддон сообщества."
L["It leads on to %s, which is neither one of Polestar's guides nor an imported one: import that guide first."] = "Он продолжается в %s, а это не гайд Polestar и не импортированный: сначала импортируйте тот гайд."
L["This import string holds a field Polestar does not read (%s). It may need a newer Polestar."] = "В строке импорта есть поле, которое Polestar не читает (%s). Возможно, нужна более новая версия Polestar."
L["Paste an import string."] = "Вставьте строку импорта."
L["This import string is too long: Polestar reads up to %d characters."] = "Строка импорта слишком длинная: Polestar читает не больше %d символов."
L["This is not a Polestar import string."] = "Это не строка импорта Polestar."
L["This game client cannot read import strings."] = "Этот игровой клиент не умеет читать строки импорта."
L["This import string holds a text longer than Polestar reads (%s): %d characters at most."] = "В строке импорта есть текст длиннее, чем читает Polestar (%s): не больше %d символов."
L["This import string holds too much: Polestar reads up to %d KB of guide data."] = "В строке импорта слишком много данных: Polestar читает не больше %d КБ данных гайда."
L["Its guide has %d goals in step %d; an import string holds %d per step at most."] = "В его гайде %d целей в шаге %d; строка импорта вмещает не более %d на шаг."
L["Its guide has %d candidates in a goal; an import string holds %d per goal at most."] = "В его гайде %d вариантов в одной цели; строка импорта вмещает не более %d на цель."
L["Its guide has more than one direct turn-in for quest %d in step %d."] = "В его гайде больше одной прямой сдачи задания %d в шаге %d."
L["Its guide has a candidate coordinate outside 0-100."] = "В его гайде есть координата-кандидат вне диапазона 0-100."
L["Its guide has a spot coordinate outside 0-100."] = "В его гайде есть координата точки вне диапазона 0-100."
L["Its guide has a map frame with missing fields."] = "В его гайде есть рамка карты с недостающими полями."
L["Its guide has a degenerate map frame (zero extent)."] = "В его гайде есть вырожденная рамка карты (нулевой размер)."
L["Its guide has a map frame with out-of-range coordinates."] = "В его гайде есть рамка карты с координатами вне допустимого диапазона."
L["No imported guides to remove."] = "Нет импортированных гайдов для удаления."
L["Removed %d imported guide(s)."] = "Удалено импортированных гайдов: %d."
L["Usage: /polestar import delete <guide-id>"] = "Использование: /polestar import delete <id-гайда>"
L["Removed imported guide %s."] = "Импортированный гайд %s удален."
L["No imported guide with id %s."] = "Нет импортированного гайда с id %s."
L["Open the Import page; import clear / import delete <id>: remove imports"] = "Открыть страницу импорта; import clear / import delete <id>: удалить импортированное"
L["Its guide has %d entries in %s; an import string holds %d there at most."] = "В гайде %d записей в разделе %s, а строка импорта вмещает там не больше %d."

