L["POLESTAR UPDATE"] = "ОБНОВЛЕНИЕ POLESTAR"
L["Check for a newer Polestar"] = "Проверьте, нет ли нового Polestar"
L["This Polestar is %d weeks old: updates come often."] = "Этой версии Polestar %d нед.: обновления выходят часто."
L["Polestar %s is out"] = "Вышел Polestar %s"
L["You're on %s, %d updates behind: fixes for the quests and arrow issues players report are in the newer versions."] = "У вас %s, пропущено обновлений: %d. Исправления проблем с заданиями и стрелкой, о которых сообщают игроки, есть в новых версиях."
L["You're on %s."] = "У вас %s."
L["Polestar %s: what's new"] = "Polestar %s: что нового"
L["Polestar releases"] = "Релизы Polestar"
L["The link is selected for you: copy it with Ctrl+C (Cmd+C on a Mac) and open it in your browser."] = "Ссылка уже выделена: скопируйте ее с помощью Ctrl+C (Cmd+C на Mac) и откройте в браузере."
L["This Polestar is %d weeks old: updates come often, check for a newer one."] = "Этой версии Polestar %d нед.: обновления выходят часто, проверьте, нет ли новой."
L["Polestar %s is out: you're on %s, %d updates behind."] = "Вышел Polestar %s: у вас %s, пропущено обновлений: %d."
L["Polestar %s is out: you're on %s."] = "Вышел Polestar %s: у вас %s."

