-- L["Copy your report with Ctrl+C (Cmd+C on a Mac), switch to Discord and paste it in the Polestar server. Not in it yet? Get the invite once and open it in your browser."] = "Скопируйте отчет (Ctrl+C, на Mac Cmd+C), перейдите в Discord и вставьте его на сервере Polestar. Еще не там? Получите приглашение и откройте его в браузере."
-- L["Next boat in about %s"] = "Следующий корабль примерно через %s"
-- L["Next zeppelin in about %s"] = "Следующий дирижабль примерно через %s"
-- L["Next tram in about %s"] = "Следующий поезд примерно через %s"
-- L["Next lift in about %s"] = "Следующий подъемник примерно через %s"
-- L["leaves in about %s"] = "отправление через ~%s"
-- L["Scale of the quest item, Hearthstone and target buttons. Drag one to move them all."] = "Масштаб кнопок предмета задания, камня возвращения и цели. Перетащите одну, чтобы сдвинуть все."
-- L["Route"] = "Маршрут"
-- L["Open the Import page: guides shared as text"] = "Открыть страницу «Импорт»: гайды, которыми поделились текстом"
-- L["Take %s"] = "Сесть на %s"
-- L["Take the lift"] = "Подняться на подъемнике"
-- L["The step you are on."] = "Ваш текущий шаг."
-- L["Points the way."] = "Указывает путь."
-- L["The map marks each place."] = "Карта отмечает каждое место."
-- L["Planned in a simulator and played to the end in tests, but nobody has followed them through the live game yet. Skip a wrong step with %s and tell us on Discord."] = "Спланированы в симуляторе и пройдены до конца в тестах, но в живой игре их еще никто не проходил. Пропустите неверный шаг с помощью %s и сообщите нам в Discord."
-- L["Feedback, bug reports and news"] = "Отзывы, сообщения об ошибках и новости"
-- L["Guides made by other players for Polestar, not our own routes: each community addon is installed like any other addon. Its guides appear in %s under Community guides, credited to their author, who supports them. More in Options > Community guides."] = "Гайды других игроков для Polestar, а не наши маршруты: каждый аддон сообщества устанавливается как любой другой аддон. Его гайды появляются в %s в разделе «Гайды сообщества» с именем автора, который их поддерживает. Подробнее: Настройки > Гайды сообщества."
-- L["How the arrow walks you. You can change it any time in Options."] = "Как вас ведёт стрелка. Это можно изменить в любой момент в настройках."
-- L["Sessions stored"] = "Сохранено сеансов"
-- L["Kept in SavedVariables until imported with the toolchain."] = "Хранятся в SavedVariables до импорта инструментами."
-- L["Events this session"] = "События за сеанс"
-- L["Character"] = "Персонаж"
-- L["Session"] = "Сеанс"
-- L["Counts and the current session in chat."] = "Счетчики и текущий сеанс в чат."
-- L["Opens the gate of the Horde's way into the City of Dalaran; one key opens it for the group. The Alliance is sent in by the Image of Archmage Modera."] = "Открывает ворота на пути Орды в город Даларан; одного ключа достаточно для всей группы. Альянс отправляет внутрь Образ верховного мага Модеры."
-- L["Accepted a resurrection."] = "Принято воскрешение."
-- L["The item the current step uses, or a quest item it collects, glows in your bags (and in Baganator)."] = "Предмет, который использует текущий шаг, или собираемый предмет задания светится в сумках (и в Baganator)."
-- L["Sells Poor-quality items when a merchant opens and prints the total. Never sells anything else."] = "Продает предметы низкого качества при открытии торговца и выводит сумму. Ничего другого не продает."
-- L["Picks the only option of NPCs without quests. Hold Shift to read it."] = "Выбирает единственный вариант у NPC без заданий. Удерживайте Shift, чтобы прочитать."
-- L["Earlier quests of this chain are not listed."] = "Ранние задания этой цепочки не указаны."
-- L["Small conveniences: travel, invitations, merchants and trackers."] = "Мелкие удобства: перемещения, приглашения, торговцы и трекеры."
-- L["Party members who run Polestar see your counts under their quest goals. Nothing goes to chat."] = "Участники группы с Polestar видят ваши счетчики под целями заданий. В чат ничего не уходит."
-- L["Their counts under your quest goals, and who lacks a quest you took."] = "Их счетчики под вашими целями и кто не взял ваше задание."
-- L["Each Polestar member's level, step and what they still need of yours; click a name to point the arrow at them. /polestar party shows or hides it."] = "Уровень и шаг каждого участника с Polestar и что ему ещё нужно из вашего шага; щелчок по имени наводит на него стрелку. /polestar party показывает или скрывает панель."
-- L["In dungeons"] = "В подземельях"
-- L["What the window does in dungeons and raids. /polestar or the key binding opens it there until you leave."] = "Поведение окна в подземельях и рейдах. Команда /polestar или назначенная клавиша откроет его до выхода из подземелья."
-- L["%s from another version"] = "%s из другой версии"
-- L["Polestar %s is installed incompletely: %s. Close the game, delete every Polestar folder in Interface/AddOns and unzip the latest Polestar zip there (CurseForge or GitHub Releases, not \"Source code\")."] = "Polestar %s установлен не полностью: %s. Закройте игру, удалите все папки Polestar в Interface/AddOns и распакуйте туда свежий zip Polestar (CurseForge или GitHub Releases, не \"Source code\")."
-- L["Objective areas"] = "Области задач"
-- L["Shade the area each group of mobs or objects spreads over on the world map."] = "Закрашивать на карте область, где встречается каждая группа мобов или объектов."
-- L["(step %d)"] = "(шаг %d)"
-- L["When an objective of a later step is close by and its quest is in your log, one line under the step says so. Click it to point the arrow there; right-click to dismiss it for this zone."] = "Когда рядом цель одного из следующих шагов, а её задание уже в журнале, об этом скажет строка под шагом. Щелчок наводит туда стрелку; правый клик скрывает строку до конца пребывания в зоне."
-- L["How near its spawn area must be for the line to show. It goes again a little further out."] = "Как близко должна быть область появления, чтобы строка показалась. Исчезает она чуть дальше."
-- L["While you're here sound"] = "Звук «Пока вы здесь»"
-- L["A soft chime when a line appears, at most every 30 seconds, at the game's sound effects volume."] = "Тихий сигнал, когда появляется строка, не чаще раза в 30 секунд, с громкостью звуковых эффектов игры."
-- L["Right-click: not now, for the rest of this zone."] = "Правый клик: не сейчас, до конца пребывания в этой зоне."
-- L["Also a quest ready to hand in whose NPC stands right here, when the guide hands it in later."] = "Также задание, готовое к сдаче, если NPC для сдачи стоит прямо здесь, а гайд сдаёт его позже."
-- L["The guide window hides in dungeons and battlegrounds. Type /polestar to show it here, or change it in Options > Guide > Window."] = "Окно гайда скрывается в подземельях и на полях боя. Введите /polestar, чтобы показать его здесь, или измените это в меню Настройки > Гайд > Окно."
-- L["What the window, its buttons and alerts do in dungeons, raids, battlegrounds and arenas. /polestar or the key binding opens it there until you leave."] = "Как ведут себя окно, его кнопки и оповещения в подземельях, рейдах, на полях боя и аренах. /polestar или назначенная клавиша открывает окно там до вашего выхода."
-- L["The target button and the step key put a raid icon on the mob and the NPC they target; out of combat, a press that finds neither clears your target. Your party sees the icons; in a raid only the leader and assistants can set them."] = "Кнопка выбора цели и клавиша шага ставят рейдовую метку на выбранного противника или NPC. Вне боя нажатие без найденной цели снимает текущее выделение. Группа видит метки; в рейде их могут ставить только лидер и помощники."
-- L["The last guides you loaded."] = "Последние загруженные гайды."
-- L["Three choices to start with. Everything else is in %s."] = "Для начала три настройки. Все остальное — в %s."
-- L["The way to the goal on the world map and the minimap: dots where you walk, lines where you fly, sail or ride, the legs after this one fainter. Drawn as Shortest Path Forever by Cillian Berragan draws them."] = "Путь к цели на карте и мини-карте: точки — где идти пешком, линии — где лететь, плыть или ехать; последующие участки бледнее. Рисуются так же, как в Shortest Path Forever от Cillian Berragan."
-- L["How the route lines are drawn: Polestar's dots, or sparkles that drift along the way to the goal."] = "Как рисуются линии маршрута: точки Polestar или искры, плывущие по пути к цели."
-- L["The first walk of %s"] = "Первый путь гайда %s"
-- L["Browse folders fold away, a closed tab comes back with Reopen, the route line can be a line, dots or sparkles on the map and minimap, and a floating Polestar button can be turned on in Options."] = "Папки в обзоре сворачиваются, закрытая вкладка возвращается кнопкой «Вернуть», маршрут на карте и миникарте может быть линией, точками или искрами, а в настройках можно включить плавающую кнопку Polestar."
-- L["Found something off?"] = "Нашли ошибку?"
-- L["Type %s right where it happens."] = "Введите %s прямо там, где это происходит."
-- L["Guide menu and minimap"] = "Меню гайдов и миникарта"
-- L["Quests asked for before the game offers them, wrong spots, dungeon pick-ups, guides opened part-way, the arrow while you're a ghost, and lots more."] = "Задания, которые требовались до того, как игра их предлагала, неверные места, взятие заданий в подземельях, гайды, открытые с середины, стрелка в облике призрака и многое другое."
-- L["Grinding steps point at where the mob is found, and on a step with several camps the arrow moves on from one you've emptied. The Target button shows who it targets, the While you're here mobs included."] = "Шаги гринда указывают, где встречается противник, а на шаге с несколькими лагерями стрелка переходит дальше от зачищенного. Кнопка цели показывает, кого выбирает, включая противников из «Пока вы здесь»."
-- L["Every leveling guide was gone over again, and 40-60 reworked for both factions with more quests and shorter grinds. Quests new in Forever carry a small ∞ mark. If the guide you had open doesn't match where you are, open the guide list and pick the guide under %s. Your quest log carries over."] = "Все гайды по прокачке заново проверены, а 40-60 переработаны для обеих фракций: больше заданий и короче гринд. Задания, новые в Forever, отмечены маленьким значком ∞. Если открытый гайд не соответствует вашему местоположению, откройте список гайдов и выберите гайд в разделе %s. Ваш журнал заданий сохраняется."
-- L["Browse folders fold away, a closed tab comes back with Reopen, the route line can be a line, dots or sparkles on the map and minimap, and the minimap button and a floating Polestar button can be turned on in Options."] = "Папки в обзоре сворачиваются, закрытая вкладка возвращается кнопкой «Вернуть», маршрут на карте и миникарте может быть линией, точками или искрами, а в настройках можно включить кнопку у миникарты и плавающую кнопку Polestar."
-- L["Leveling guides take you through this dungeon where they have steps for it. Off: they keep to the solo route."] = "Гайды по прокачке проводят вас через это подземелье, если в них есть шаги для него. Если выключено, они придерживаются одиночного маршрута."
-- L["With Transparent, a shade with no edge behind the text, so it reads over bright ground. Off: the outlined text alone on the world."] = "В прозрачном стиле — тень без краёв за текстом, чтобы его было видно на ярком фоне. Выкл.: только обведённый текст поверх мира."
-- L["The route's line, dots or sparkles on the minimap, and the gaps between the dots; the world map keeps its own. Right-click to reset."] = "Линия, точки или искры маршрута на миникарте и промежутки между точками; у карты мира своя настройка. ПКМ — сброс."
-- L["Behind: %s (%d) at step %d, you'll be %s; grind ~%s first"] = "Отставание: %s (%d) на шаге %d, у вас будет %s; сначала прокачайтесь ~%s"
-- L["Behind: %s (%d) at step %d, you'll be %s; reach %d first"] = "Отставание: %s (%d) на шаге %d, у вас будет %s; сначала достигните %d"
-- L["1 bar"] = "1 полоска"
-- L["%d bars"] = "Полосок: %d"
-- L["On pace, but %s (%d) at step %d is hard: you'll be %s; grind ~%s first"] = "Темп в норме, но %s (%d) на шаге %d будет трудным: у вас будет %s; сначала набейте ~%s"
-- L["On pace, but %s (%d) at step %d is hard: you'll be %s; reach %d first"] = "Темп в норме, но %s (%d) на шаге %d будет трудным: у вас будет %s; сначала достигните %d"
-- L["Hide the guide window"] = "Скрыть окно гайда"
-- L["A Polestar button on the edge of the minimap. Click to show or hide the guide, right-click for settings, drag to move it."] = "Кнопка Polestar на краю миникарты. Щелчок показывает или скрывает гайд, правый щелчок открывает настройки, перетаскивание перемещает ее."
-- L["Click the minimap button or press %s to show it."] = "Щелкните кнопку у миникарты или нажмите %s, чтобы показать его."
-- L["Click the minimap button to show it."] = "Щелкните кнопку у миникарты, чтобы показать его."
-- L["What the window, its buttons and alerts do in dungeons, raids, battlegrounds and arenas. The minimap button, the key binding or /polestar opens it there until you leave."] = "Что делают окно, его кнопки и оповещения в подземельях, рейдах, на полях боя и аренах. Кнопка у миникарты, назначенная клавиша или /polestar открывает его там до вашего выхода."
-- L["A small Polestar button you can put anywhere on the screen. Click to show or hide the guide, right-click for a menu, drag to move it. It hides with the window in combat and in dungeons when those are set to Hide."] = "Маленькая кнопка Polestar, которую можно разместить в любом месте экрана. Щелчок показывает или скрывает гайд, ПКМ — меню, перетаскивание перемещает ее. Она скрывается вместе с окном в бою и в подземельях, если для них выбрано «Скрыть»."
-- L["Click: show or hide the guide"] = "Щелчок: показать или скрыть гайд"
-- L["Show window"] = "Показать окно"
-- L["How near its spawn area must be for a suggestion to show. It goes again a little further out."] = "Насколько близко должна быть область появления, чтобы показать подсказку. Она исчезает чуть дальше."
-- L["How deep the night runs. Dusk is the default, Night the darkest, Graphite a neutral grey; EllesmereUI takes its panel colour and accent."] = "Насколько темна ночь. Сумерки — по умолчанию, Ночь — самая темная, Графит — нейтральный серый; EllesmereUI берет свой цвет панели и акцент."
-- L["Appearance"] = "Внешний вид"
-- L["Points to the current goal. Its look and colours are under Appearance, Arrow."] = "Указывает на текущую цель. Вид и цвета — в разделе «Внешний вид», «Стрелка»."
-- L["Colour & type"] = "Цвет и шрифт"
-- L["Colours, type, window frames and the arrow. Everything repaints as you change it; right-click a setting to reset it."] = "Цвета, шрифт, рамки окон и стрелка. Все перерисовывается сразу; ПКМ по настройке — сбросить ее."
-- L["Type & motion"] = "Шрифт и анимация"
-- L["Frame"] = "Рамка"
-- L["The whole guide window, text included. The background's own opacity is under Colour & type."] = "Все окно гайда вместе с текстом. Непрозрачность самого фона — в разделе «Цвет и шрифт»."
-- L["Map icons"] = "Значки на карте"
-- L["Polestar's marks on the minimap; the world map keeps its own. A mark over your arrow fades so the arrow shows through it. Right-click to reset."] = "Метки Polestar на мини-карте; на карте мира свои метки. Метка над вашей стрелкой становится прозрачной, чтобы стрелку было видно. Правый щелчок — сброс."
-- L["Sparkle"] = "Искры"
-- L["Subtle"] = "Мягко"
-- L["Dazzling"] = "Ослепительно"
-- L["Route line style"] = "Стиль линии маршрута"
-- L["Route colours tint each leg by how you travel it. Cyan, magenta and white stand apart from the minimap's yellow herb and ore dots and its gold quest marks. Right-click to reset."] = "Цвета маршрута окрашивают каждый участок по способу перемещения. Голубой, пурпурный и белый отличаются от желтых точек трав и руды на миникарте и ее золотых меток заданий. ПКМ — сброс."
-- L["How thick the solid line is on the world map; the minimap's follows its size. Right-click to reset."] = "Толщина сплошной линии на карте мира; на миникарте она следует размеру. ПКМ — сброс."
-- L["Reset to default"] = "Сбросить по умолчанию"
-- L["Button size"] = "Размер кнопок"
-- L["Target name position"] = "Положение имени цели"
-- L["Scale of the quest item, Hearthstone, target and rare buttons. Drag one to move them all."] = "Масштаб кнопок задания, камня возвращения, выбора цели и редкой цели. Перетащите одну, чтобы переместить все."
-- L["Accent colour"] = "Цвет акцента"
-- L["Background opacity"] = "Непрозрачность фона"
-- L["Border thickness"] = "Толщина рамки"
-- L["Window scale"] = "Масштаб окна"
-- L["Window opacity"] = "Непрозрачность окна"
-- L["Menus"] = "Меню"
-- L["Arrow style"] = "Стиль стрелки"
-- L["Arrow scale"] = "Масштаб стрелки"
-- L["Arrow opacity"] = "Непрозрачность стрелки"
-- L["Colours"] = "Цвета"
-- L["Arrival colour"] = "Цвет прибытия"
-- L["The arrow as it closes on the target, and the ring when you arrive. Right-click to go back to jade."] = "Стрелка при приближении к цели и кольцо по прибытии. ПКМ — вернуть нефритовый."
-- L["Class quest chime"] = "Звук классового задания"
-- L["A short chime the first time a class quest chain's card shows. Off while the game's sound effects are off."] = "Короткий звуковой сигнал при первом показе карточки цепочки классовых заданий. Не звучит, если звуковые эффекты в игре отключены."
-- L["Minimap icon size"] = "Размер значков на мини-карте"
-- L["Button in the game menu"] = "Кнопка в игровом меню"
-- L["Keep the bar shown"] = "Не скрывать панель"
-- L["How bright each sparkle and its glow are."] = "Яркость каждой искры и ее свечения."
-- L["How close together the sparkles sit, the same at any zoom."] = "Насколько близко друг к другу расположены искры, одинаково при любом масштабе."
-- L["Flow toward goal"] = "Движение к цели"
-- L["Most sparkles shown"] = "Максимум искр"
-- L["Line thickness"] = "Толщина линии"
-- L["How strongly the route shows on the minimap, line, dots or sparkles; the world map keeps its own. Right-click to reset."] = "Насколько заметен маршрут на миникарте — линия, точки или искры; у карты мира своя настройка. ПКМ — сброс."
-- L["The route's line, dots or sparkles on the minimap, each style its own size; the world map keeps its own. Right-click to reset."] = "Линия, точки или искры маршрута на миникарте, у каждого стиля свой размер; у карты мира свой. ПКМ — сброс."
-- L["Tooltips and quest log"] = "Подсказки и журнал заданий"
-- L["Comparison"] = "Сравнение"
-- L["Rares & travel"] = "Редкие и перемещения"
-- L["Instance limits"] = "Лимиты подземелий"
-- L["The XP tracker is off (Options > Quality of Life > Trackers)."] = "Счетчик опыта выключен (Настройки > Удобство > Трекеры)."
-- L["Learn new spells"] = "Изучать новые заклинания"
-- L["Learns every spell a class trainer offers that you can afford, and prints the total. Profession trainers are left alone. Hold Shift to skip."] = "Изучает у учителя классовых навыков все доступные по деньгам заклинания и выводит сумму. Учителей профессий не трогает. Удерживайте Shift, чтобы пропустить."
-- L["Loot and merchants"] = "Добыча и торговцы"
-- L["Dungeons are turned off (Options > Discovery > Dungeons)."] = "Подземелья выключены (Настройки > Открытия > Подземелья)."
-- L["The Dungeons section is turned off. Turn it on under Options > Discovery > Dungeons."] = "Раздел подземелий отключен. Включите его в Настройки > Открытия > Подземелья."
-- L["History"] = "История"
-- L["Polestar's own look (the default), Halo (no frame, a soft dark veil, Fira Sans), Hearth (warm game colours), or the game's own art: WoW Forever, Blizzard and Classic. Style, compact mode and the colours you pick work in each."] = "Собственный вид Polestar (по умолчанию), Ореол (без рамки, мягкая темная вуаль, Fira Sans), Очаг (теплые цвета игры) или собственная графика игры: WoW Forever, Blizzard и Classic. Стиль, компактный режим и выбранные цвета работают в каждом оформлении."
