-- L["Dungeons and battlegrounds"] = "Подземелья и поля боя"
-- L["How near its spawn area must be for a suggestion to show. It goes again a little further out."] = "Насколько близко должна быть область появления, чтобы показать подсказку. Она исчезает чуть дальше."
-- L["When %s comes into sight, a card says so and the rare button targets him and waves. At most once every half hour, never in combat or instances."] = "Когда %s появляется в поле зрения, об этом сообщает карточка, а кнопка редкой цели выбирает его и машет. Не чаще раза в полчаса, никогда в бою или в подземельях."
-- L["Characters is turned off. Turn it on under Options > Discovery > Characters."] = "Раздел «Персонажи» отключен. Включите его в меню «Настройки > Обзор > Персонажи»."
-- L["Dungeon heads-ups are off. Turn them back on under Options > Discovery > Dungeons."] = "Уведомления о подземельях отключены. Включить их снова можно в разделе Настройки > Открытия > Подземелья."
